window.STUDY_DATA = {"version": 4, "deckType": "concept", "modules": ["Analytics foundations", "Classification and preparation", "Validation and selection", "Clustering and distance", "Outliers", "Change detection", "Time series", "Regression and inference", "PCA and transformations", "Trees, probabilities, and decisions"], "cards": [{"id": "R-001", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is descriptive analytics?", "answer": "Summarizes observed patterns and relationships.", "explanation": "Descriptive analytics organizes information already observed so patterns are easier to understand. Counts, averages, plots, and summaries can reveal differences between groups or changes over time. For example, a library can summarize borrowing by month. The summary alone does not predict next month's demand or establish why borrowing changed.", "links": [], "objective": "what-is-descriptive-analytics"}, {"id": "R-002", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is predictive analytics?", "answer": "Estimates unknown or future outcomes.", "explanation": "Predictive analytics uses available information to estimate a response that is not yet known. A fitted relationship must be evaluated on cases it did not learn from. For example, building attributes can predict electricity use. Good historical fit is useful only if the relationship and inputs transfer to the intended prediction setting.", "links": [], "objective": "what-is-predictive-analytics"}, {"id": "R-003", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is prescriptive analytics?", "answer": "Chooses actions using objectives, constraints, and consequences.", "explanation": "Prescriptive analytics turns information into an action by considering an objective and constraints. A demand forecast can inform staffing, but a staffing decision also needs labor costs, service requirements, and available workers. Prediction supplies an input; choosing a feasible action that best serves the objective is a separate task.", "links": [], "objective": "what-is-prescriptive-analytics"}, {"id": "R-004", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What can the term model refer to?", "answer": "A method family, a predictor specification, or a fitted numerical model.", "explanation": "The word model can describe different stages of the same process. Linear regression names a method family; choosing response and predictor columns specifies a model structure; estimating its intercept and slopes produces a fitted model. Distinguishing these meanings clarifies whether you are selecting a procedure, choosing its inputs, or estimating numerical values.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-can-the-term-model-refer-to"}, {"id": "R-005", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is the modeling cycle from reality to recommendations?", "answer": "Represent reality mathematically, analyze it, then interpret the result in context.", "explanation": "A model simplifies a real situation into quantities, relationships, and assumptions that can be analyzed. The resulting numbers must then be translated back into a practical recommendation. For example, clustering locations creates mathematical groups, but using them for delivery requires checking roads, access, capacity, and whether the chosen distance represents actual service effort.", "links": [], "objective": "what-is-the-modeling-cycle-from-reality-to-recommendations"}, {"id": "R-006", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "Why must model choice begin with the operational question?", "answer": "Different questions require different outputs.", "explanation": "Start by naming the desired output and how it will be used. Predicting a numeric amount, assigning a class, discovering groups, and choosing an action are different questions. For example, clustering customers does not directly estimate whether they will renew. An appropriate model family must produce information that answers the operational question.", "links": [], "objective": "why-must-model-choice-begin-with-the-operational-question"}, {"id": "R-008", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "What is the difference between statistical inference and prediction?", "answer": "Inference examines relationships; prediction estimates new outcomes.", "explanation": "Inference focuses on what fitted relationships suggest about the underlying process, including uncertainty in estimated effects. Prediction focuses on estimating outcomes for new cases. An interpretable coefficient may help explain a relationship without producing the best forecast. Conversely, a strong predictor can be difficult to interpret and does not automatically establish a causal mechanism.", "links": [], "objective": "what-is-the-difference-between-statistical-inference-and-prediction"}, {"id": "R-010", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "How should interpretability affect model selection?", "answer": "Balance explanation requirements against predictive performance and operational usefulness.", "explanation": "Interpretability matters when a decision needs an explanation, an auditable rule, or insight into relationships. A small tree may offer a readable sequence of decisions, while a forest may improve prediction through aggregation. Compare models against both validation performance and the practical explanation requirement; neither simplicity nor complexity alone establishes suitability.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-should-interpretability-affect-model-selection"}, {"id": "R-011", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "Why can a mathematically good fit still be operationally unsuitable?", "answer": "A model can answer its mathematical question while missing the actual operational goal.", "explanation": "Fit measures describe performance on a mathematical target, which may differ from the actual business goal. A classifier with high accuracy can still miss the few cases carrying most of the cost. Check that the response, evaluation metric, available inputs, and intended population match the decision the model is supposed to support.", "links": [], "objective": "why-can-a-mathematically-good-fit-still-be-operationally-unsuitable"}, {"id": "R-012", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "stem": "How does an outcome prediction differ from choosing an action?", "answer": "Prediction estimates an outcome; a decision also considers actions, costs, and constraints.", "explanation": "An outcome prediction answers what is likely to happen given the available information. Choosing an action also requires evaluating consequences, costs, resources, and constraints. A predicted equipment failure probability does not by itself determine replacement: the decision depends on the costs of replacement, failure, inspection, and possible delays.", "links": [], "objective": "how-does-an-outcome-prediction-differ-from-choosing-an-action"}, {"id": "C-001", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "objective": "unknown-present-prediction", "stem": "Must a predictive target describe the future?", "answer": "No. Prediction can estimate an unknown present response as well as a future response.", "explanation": "Prediction refers to estimating an unknown response, rather than necessarily forecasting forward in time. A model might estimate an unmeasured property of an object that already exists, or predict next week's sales. Both require inputs available when the estimate is made and evaluation on representative cases whose responses were not used for fitting.", "links": []}, {"id": "C-002", "module": 1, "topic": "Analytics foundations", "kind": "concept", "source": "Concept", "objective": "fitted-parameter-versus-setting", "stem": "How do learned parameters differ from chosen model settings?", "answer": "Parameters are fitted values such as slopes or centers; settings choose structure or tradeoffs such as k or a penalty.", "explanation": "Learned parameters are estimated from the training data, such as regression slopes or cluster-center coordinates. Chosen settings define how fitting proceeds, such as the number of neighbors or an error penalty. Some terminology groups both as parameters, so identify their roles. Validation can help choose settings; training then estimates the corresponding fitted values.", "links": [{"label": "ISLR author companion courses", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-013", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What do rows and columns normally represent in a data table?", "answer": "Rows: observations. Columns: attributes, predictors, and possibly the response.", "explanation": "In a typical rectangular dataset, each row describes one observation and each column records one attribute. A supervised-learning table also includes a response column. For example, a row may describe one shipment, with distance and weight as predictors and delivery time as the response. Define the unit of observation before interpreting the columns.", "links": [], "objective": "what-do-rows-and-columns-normally-represent-in-a-data-table"}, {"id": "R-014", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Which names are used for explanatory variables?", "answer": "Attributes, features, predictors, covariates, and independent variables.", "explanation": "These terms commonly describe the inputs used to explain or predict a response. Calling a variable independent does not imply that it is statistically independent of other inputs. For example, floor area and number of rooms can both be predictors while being strongly related. Interpret the label as a modeling role, not an independence guarantee.", "links": [{"label": "StatQuest video catalog: nearest neighbors", "url": "https://statquest.org/video_index.html"}, {"label": "ISLR statistical-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "which-names-are-used-for-explanatory-variables"}, {"id": "R-015", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does the response differ from a predictor?", "answer": "The response is what you estimate; predictors are the information used.", "explanation": "The response is the quantity the model is asked to estimate; predictors provide information for that estimate. Their roles depend on the task, rather than being intrinsic properties of a column. Temperature can predict power usage in one model and be the response in another. Predictors must be available at the intended decision time.", "links": [], "objective": "how-does-the-response-differ-from-a-predictor"}, {"id": "R-016", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How do quantitative and categorical data differ?", "answer": "Quantitative values measure amounts; categorical values identify groups.", "explanation": "Quantitative data describe amounts for which numerical differences have meaning. Categorical data describe membership in groups, even when groups are stored as numbers. For example, package weight is quantitative, while service category is categorical. The distinction affects representation and whether operations such as averaging or computing coordinate distances are meaningful.", "links": [], "objective": "how-do-quantitative-and-categorical-data-differ"}, {"id": "R-017", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why should numeric identifiers not automatically define quantitative distances?", "answer": "Identifier numbers name categories; their differences need not represent meaningful similarity.", "explanation": "A numeric identifier is a name encoded with digits. A difference of ten between account IDs need not imply more similarity than a difference of a thousand. Distance-based methods can therefore be misled if such codes are treated as measurements. Use a representation that captures meaningful attributes instead of arbitrary numbering.", "links": [], "objective": "why-should-numeric-identifiers-not-automatically-define-quantitative-distances"}, {"id": "R-018", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a binary variable?", "answer": "A variable with two possible categories.", "explanation": "A binary variable has exactly two possible categories, such as pass/fail or present/absent. Coding the categories as zero and one can simplify calculations and modeling. The coding convention still matters: a one represents the event you explicitly choose, and reversing the labels changes how probabilities and classification metrics should be interpreted.", "links": [], "objective": "what-is-a-binary-variable"}, {"id": "R-019", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does structured data differ from unstructured data?", "answer": "Structured data has defined fields; unstructured input needs a suitable representation.", "explanation": "Structured data have defined fields, such as dates, quantities, and categories in a table. Unstructured inputs, such as text or images, usually need conversion into features before the surveyed models can use them. The representation should retain information relevant to the task; converting input into columns does not automatically make those columns meaningful.", "links": [], "objective": "how-does-structured-data-differ-from-unstructured-data"}, {"id": "R-020", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What makes data a time series?", "answer": "Observations have a meaningful temporal order.", "explanation": "Time-series observations are indexed in an order that matters for interpretation and prediction. Past values, changes, and repeating phases can contain information about later values. Reordering the rows destroys those relationships. For forecasting, training and evaluation must respect which observations and inputs would have been available before the prediction time.", "links": [], "objective": "what-makes-data-a-time-series"}, {"id": "R-021", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is supervised learning?", "answer": "Learning from observations with known responses.", "explanation": "Supervised learning uses cases with known responses to learn an input-to-output relationship. Classification uses categorical responses; regression generally uses numeric responses. For example, known renewal outcomes can train a renewal classifier. The fitted relationship must then be checked on held-out cases, because explaining the training labels is not sufficient evidence of generalization.", "links": [], "objective": "what-is-supervised-learning"}, {"id": "R-022", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is unsupervised learning?", "answer": "Learning patterns without known response labels.", "explanation": "Unsupervised learning examines structure in the inputs without a known response guiding the fit. Clustering finds groups under a chosen similarity definition, while PCA finds directions of predictor variation. A discovered group is not automatically a known class, and a high-variance component is not automatically useful for predicting a later response.", "links": [], "objective": "what-is-unsupervised-learning"}, {"id": "R-023", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is classification?", "answer": "Predicting a category or class.", "explanation": "Classification assigns a case to a category based on its features. The response may be binary or have several classes. A classifier's score, probability estimate, and final class label are distinct outputs. For example, a probability of renewal becomes a yes/no prediction only after a decision threshold or other assignment rule is chosen.", "links": [], "objective": "what-is-classification"}, {"id": "R-024", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a linear classifier's decision function?", "answer": "f(x)=b+sum(w_j*x_j); classify using its sign or a specified threshold.", "explanation": "A linear classifier combines predictors into a score f(x)=b+sum(w_j*x_j). Its boundary occurs where the score reaches the chosen decision threshold, commonly zero. The weights determine orientation and the intercept shifts the boundary. The assignment at equality must be specified; the numerical score alone is not automatically an event probability.", "links": [], "objective": "what-is-a-linear-classifier-s-decision-function"}, {"id": "R-025", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a vertical classifier boundary imply in an x1-horizontal,x2-vertical plot?", "answer": "Only x1 controls that fitted threshold rule.", "explanation": "With x1 on the horizontal axis, a vertical boundary fixes a threshold on x1 while allowing x2 to vary freely. Therefore x2 has no effect on this particular fitted decision rule. For example, x1>4 can assign one class throughout the right region. This does not prove x2 has no relevance to every possible model.", "links": [], "objective": "what-does-a-vertical-classifier-boundary-imply-in-an-x1-horizontal-x2-vertical-plot", "diagram": "vertical"}, {"id": "R-026", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a horizontal classifier boundary imply in an x1-horizontal,x2-vertical plot?", "answer": "Only x2 controls that fitted threshold rule.", "explanation": "With x2 on the vertical axis, a horizontal boundary fixes a threshold on x2 regardless of x1. Cases above and below the line receive different classes under the specified convention. The x1 coefficient is zero in that fitted linear rule. Always check the axis labels before deciding which predictor controls the classification.", "links": [], "objective": "what-does-a-horizontal-classifier-boundary-imply-in-an-x1-horizontal-x2-vertical-plot", "diagram": "horizontal"}, {"id": "R-027", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is a hyperplane?", "answer": "A linear separating boundary in multiple dimensions.", "explanation": "A hyperplane is defined by a linear equation in the predictor coordinates, such as b+sum(w_j*x_j)=0. In two dimensions it is a line; in three it is a plane. It separates the space into regions determined by the sign of the score. Its simplicity concerns the represented coordinates, which may themselves be transformed features.", "links": [], "objective": "what-is-a-hyperplane"}, {"id": "R-028", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What objective distinguishes a hard-margin SVM?", "answer": "Correctly separate the training classes with the widest margin to the nearest class points.", "explanation": "A hard-margin SVM seeks a separating boundary that classifies all training cases correctly while maximizing the nearest-point margin. It requires separable training classes in the chosen representation. The closest constraining points determine the geometry. Perfect training separation is part of this objective, but does not by itself guarantee good predictions on new cases.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-objective-distinguishes-a-hard-margin-svm"}, {"id": "R-029", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why does the hard-margin SVM derivation use labels -1/+1?", "answer": "They let one signed condition describe both classes.", "explanation": "Using y=-1 for one class and y=+1 for the other combines two class-specific inequalities into y*f(x)>=1 under the usual margin normalization. A correctly signed score makes the product positive for either class. These labels are an algebraic convenience for the derivation, rather than a claim that one category is numerically smaller.", "links": [], "objective": "why-does-the-hard-margin-svm-derivation-use-labels-1-1"}, {"id": "R-031", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What are support vectors in the separable SVM picture?", "answer": "The nearest training points that constrain the margin.", "explanation": "In the separable picture, support vectors are the training observations lying on the margin boundaries. They constrain how wide the margin can become. Many observations farther inside the correctly classified regions can move without changing the solution. This geometric role differs from simply calling every training observation equally important to the fitted boundary.", "links": [], "objective": "what-are-support-vectors-in-the-separable-svm-picture"}, {"id": "R-032", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why use a soft-margin classifier?", "answer": "To balance margin against fitting errors when strict separation is unsuitable.", "explanation": "A soft-margin classifier permits margin violations so it can handle overlapping classes or avoid distorting a boundary around unusual cases. The objective balances fit penalties against the margin-related coefficient penalty. Allowing violations does not mean ignoring errors: their contribution is explicitly controlled, and the tradeoff should be selected using relevant held-out performance.", "links": [], "objective": "why-use-a-soft-margin-classifier"}, {"id": "R-035", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does lambda act in the stated SVM objective loss + lambda*norm(w)^2?", "answer": "Increasing lambda emphasizes the coefficient penalty rather than training fit.", "explanation": "In loss+lambda*norm(w)^2, lambda multiplies the coefficient penalty. Increasing it places more emphasis on smaller weights relative to fitting the training labels. Decreasing it emphasizes fit more strongly. Interpret the actual objective, because software may use a parameter that multiplies loss instead and therefore moves the tradeoff in the opposite direction.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-lambda-act-in-the-stated-svm-objective-loss-lambda-norm-w-2"}, {"id": "R-036", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Can a shared parameter symbol be interpreted the same way across different model specifications?", "answer": "Its effect depends on the model and the term it controls.", "explanation": "A symbol only acquires meaning from the formula or procedure in which it appears. For example, a CUSUM allowance and an SVM error penalty can both be called C while controlling unrelated quantities. Even two SVM implementations can place penalties differently. Locate the term controlled by the setting before predicting the effect of increasing it.", "links": [], "objective": "can-a-shared-parameter-symbol-be-interpreted-the-same-way-across-different-model-specifications"}, {"id": "R-037", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How should an SVM tradeoff setting be selected?", "answer": "Compare held-out performance under the relevant error costs; training perfection is insufficient.", "explanation": "Compare candidate tradeoff settings on validation data using a metric that reflects the intended decisions. A setting that eliminates training mistakes can fit noise or produce an unsuitable boundary for new cases. If false positives and false negatives have different costs, incorporate those consequences instead of selecting by training accuracy alone.", "links": [], "objective": "how-should-an-svm-tradeoff-setting-be-selected"}, {"id": "R-038", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How can SVM handle unequal mistake costs?", "answer": "Change error penalties or the decision boundary to reflect unequal consequences.", "explanation": "When mistakes have unequal consequences, an SVM can use different penalties for errors in different classes or an appropriately chosen decision rule. For example, missing a dangerous defect may be more costly than flagging a good item. Evaluate the resulting tradeoff on held-out cases; increasing detection can also increase false alarms.", "links": [], "objective": "how-can-svm-handle-unequal-mistake-costs"}, {"id": "R-039", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What does a kernel SVM add?", "answer": "A more flexible, potentially nonlinear separating boundary.", "explanation": "A kernel lets an SVM create nonlinear separation in the original input space while retaining its margin-based approach. This flexibility can capture structure a straight boundary misses. It also introduces choices that require validation. A more flexible boundary is a candidate model, not a guarantee of superior performance or a reason to expand beyond the task.", "links": [], "objective": "what-does-a-kernel-svm-add"}, {"id": "R-040", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why is an SVM score not automatically a probability?", "answer": "It is a decision score, not automatically a fitted event probability.", "explanation": "An SVM score indicates a case's position relative to the decision boundary under the fitted model. Its magnitude and sign support classification, but its scale is not inherently zero to one. Therefore a score such as 0.8 cannot simply be read as an 80% event probability without an additional probability-estimation procedure.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-an-svm-score-not-automatically-a-probability"}, {"id": "R-041", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is k-NN classification's prediction rule?", "answer": "Choose the most frequent label among the k nearest training cases.", "explanation": "For a new case, k-NN finds the k closest labeled training cases using the selected representation and distance rule. It predicts the most frequent class among them. For example, three votes for class A and two for B yield A when k=5. Scaling, irrelevant features, and tie rules can all affect which prediction results.", "links": [], "objective": "what-is-k-nn-classification-s-prediction-rule"}, {"id": "R-042", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Does a multiclass k-NN winner require more than half the votes?", "answer": "No. A plurality is enough.", "explanation": "With more than two classes, the winning class can have the largest vote count without having a majority of all votes. Counts of 4, 3, and 2 give the first class a plurality among nine neighbors. A majority would require more than half. Specify a tie-breaking rule when several classes share the largest count.", "links": [], "objective": "does-a-multiclass-k-nn-winner-require-more-than-half-the-votes"}, {"id": "R-043", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can odd k still produce a k-NN tie?", "answer": "Multiclass vote counts or equal distances can still tie.", "explanation": "Odd k prevents an equal two-class vote split when every neighbor has one vote, but it does not prevent every possible tie. With three classes and k=9, counts of 4, 4, and 1 tie for first. Equal distances at the neighborhood boundary also require a rule for which cases to include.", "links": [], "objective": "why-can-odd-k-still-produce-a-k-nn-tie"}, {"id": "R-044", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How does increasing k generally affect neighbor predictions?", "answer": "Larger neighborhoods generally smooth local variation.", "explanation": "Increasing k averages or votes across a larger neighborhood, reducing sensitivity to individual nearby cases. This can stabilize predictions but can also blend distinct local patterns. Small k is more responsive to local structure and noise. Select the neighborhood size through suitable validation rather than assuming either the smallest or largest value is always best.", "links": [], "objective": "how-does-increasing-k-generally-affect-neighbor-predictions"}, {"id": "R-045", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can irrelevant dimensions hurt k-NN?", "answer": "They can distort which cases appear close.", "explanation": "Distance uses all included coordinates, so an irrelevant feature can make truly similar cases appear far apart. Many such features can overwhelm the informative differences. For example, arbitrary recorded attributes may change neighbor rankings without helping predict the response. Thoughtful feature representation and scaling are therefore important parts of a k-NN procedure.", "links": [], "objective": "why-can-irrelevant-dimensions-hurt-k-nn"}, {"id": "R-046", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is min-max scaling to zero and one?", "answer": "(x-training minimum)/(training maximum-training minimum).", "explanation": "Min-max scaling maps the training minimum to zero and maximum to one using (x-min)/(max-min). A value of 15 with training endpoints 10 and 20 maps to 0.5. Reuse those endpoints for new cases. If the range is zero, the division is undefined and the constant feature needs explicit handling.", "links": [], "objective": "what-is-min-max-scaling-to-zero-and-one"}, {"id": "R-047", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "How do you scale u in [0,1] to endpoints a and b?", "answer": "a+(b-a)*u.", "explanation": "Once u is expressed on the zero-to-one scale, a+(b-a)*u maps it to a chosen interval. Zero maps to a, one to b, and intermediate values retain their relative positions. For example, u=0.25 maps to 3 when a=2 and b=6. This is a coordinate conversion, not a learned predictive relationship.", "links": [], "objective": "how-do-you-scale-u-in-0-1-to-endpoints-a-and-b"}, {"id": "R-048", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "What is standardization?", "answer": "(x-training mean)/training standard deviation.", "explanation": "Standardization subtracts the training mean and divides by the training standard deviation. This produces coordinates in standard-deviation units and can make differently measured features more comparable. It does not make a distribution normal. Apply the same training mean and scale to new cases, and handle zero standard deviation explicitly.", "links": [], "objective": "what-is-standardization"}, {"id": "R-049", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "When do scaling formulas need special handling?", "answer": "When the feature's range or standard deviation is zero.", "explanation": "A constant training feature has no range and no standard deviation, so the usual scaling formulas divide by zero. Decide how to represent or remove it rather than letting invalid values propagate. It contributes no within-training variation, but new cases should still be handled consistently with the representation used to fit the model.", "links": [], "objective": "when-do-scaling-formulas-need-special-handling"}, {"id": "R-050", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "stem": "Why can future min-max scaled values exceed one or fall below zero?", "answer": "New observations can lie outside the training range.", "explanation": "Min-max scaling uses fixed training endpoints, rather than constraining every future value to the interval. A new value above the training maximum produces a scaled value above one; one below the minimum produces a negative value. This is mathematically consistent. Refitting endpoints on new cases would change the coordinate system expected by the model.", "links": [], "objective": "why-can-future-min-max-scaled-values-exceed-one-or-fall-below-zero"}, {"id": "C-003", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "knn-required-inputs", "stem": "What information does k-NN classification need?", "answer": "Labeled training cases, a feature representation and distance rule, a neighborhood size, and tie handling.", "explanation": "k-NN needs retained labeled cases, comparable feature coordinates, a distance definition, and a chosen neighborhood size. It also needs a rule for ties or equally distant boundary cases. There is no useful notion of nearest without defining the representation. Classification then votes among neighbor labels, while neighbor regression averages their numeric responses.", "links": []}, {"id": "C-004", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "svm-required-inputs", "stem": "What information and choices define an SVM classification problem?", "answer": "Predictor features, known class labels, an appropriate representation, and the specified margin/error tradeoff.", "explanation": "An SVM uses known class labels and a feature representation to fit a separating rule. Its specification determines whether strict separation is required, how violations are penalized, and whether the boundary can be nonlinear. Choose these settings for the task and validate them. The trained coefficients or support information are fitted results, not additional response labels.", "links": [{"label": "StatQuest SVM video", "url": "https://youtu.be/efR1C6CvhmE"}, {"label": "ISLR classification resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-005", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "boundary-equality-convention", "stem": "How is a case exactly on a classifier boundary assigned?", "answer": "Use the stated inequality and label convention; equality handling must be specified.", "explanation": "A case whose decision score equals the threshold belongs to neither strict side unless the assignment convention specifies equality. Rules f>=0 and f>0 handle it differently. This is a boundary convention, not a failure of the score calculation. State it explicitly when interpreting a diagram or implementing a classifier.", "links": []}, {"id": "C-006", "module": 2, "topic": "Classification and preparation", "kind": "concept", "source": "Concept", "objective": "new-case-fitted-scaler", "stem": "Why must new cases use the training scaler?", "answer": "The fitted model expects the same coordinate system; independent recentering or rescaling changes input meaning.", "explanation": "Learned scaling defines the coordinates in which the model was fitted. New cases must use those same means, ranges, or standard deviations. Independently scaling a new batch can give an identical physical value different coordinates. That changes distances and fitted scores even though the underlying case has not changed.", "links": [{"label": "scikit-learn preprocessing reference", "url": "https://scikit-learn.org/stable/modules/preprocessing.html"}]}, {"id": "R-051", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why is training accuracy an optimistic estimate of future performance?", "answer": "The model was fitted to those same observations.", "explanation": "Training observations directly influenced the fitted model, so their performance reflects both useful learning and accommodation of that particular sample. This makes training accuracy an optimistic estimate for unseen cases. Use representative held-out evaluation to assess generalization, and avoid repeatedly adjusting the procedure based on the supposedly final test results.", "links": [], "objective": "why-is-training-accuracy-an-optimistic-estimate-of-future-performance"}, {"id": "R-052", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is overfitting?", "answer": "Fitting sample-specific noise that does not generalize.", "explanation": "Overfitting occurs when the model captures sample-specific irregularities instead of only useful underlying structure. It can produce excellent training performance with much weaker validation performance. More flexible models have more opportunities to do this, but complexity alone is not the diagnosis. The key evidence is failure to generalize to appropriate held-out cases.", "links": [], "objective": "what-is-overfitting"}, {"id": "R-053", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is underfitting?", "answer": "A model is too restrictive to capture useful structure.", "explanation": "Underfitting occurs when the chosen representation or model is too restrictive to capture important structure. Both training and held-out performance can be poor. For example, a straight-line relationship may miss a strong curve. Adding the right structure can help, but increasing complexity indiscriminately can move the procedure from underfitting toward overfitting.", "links": [], "objective": "what-is-underfitting"}, {"id": "R-054", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the training set's role?", "answer": "Fit the model and learned preprocessing.", "explanation": "Training data supply the observations used to estimate model parameters and any learned preprocessing. A regression fits slopes, clustering fits centers, and standardization estimates means and scales. These quantities should not incorporate held-out responses or learned statistics from evaluation cases. The training boundary applies to the complete procedure, rather than only the final model fit.", "links": [], "objective": "what-is-the-training-set-s-role"}, {"id": "R-055", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the validation set's role?", "answer": "Choose among candidate models and settings.", "explanation": "Validation data compare candidate specifications, settings, or modeling choices without fitting each candidate directly to those cases. For example, validation can choose k for k-NN. Because the selected procedure depends on these scores, validation performance is not a fully independent final evaluation. Keep a separate test set when that independence is needed.", "links": [], "objective": "what-is-the-validation-set-s-role"}, {"id": "R-056", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is the test set's role?", "answer": "Evaluate the selected procedure independently.", "explanation": "A test set evaluates the procedure after fitting and selection decisions are complete. It should represent the intended deployment cases and remain outside model selection. Repeatedly changing the model to improve its test score makes that set act as validation data. Its name does not preserve independence once its results influence the procedure.", "links": [], "objective": "what-is-the-test-set-s-role"}, {"id": "R-057", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why can the best validation score be too favorable?", "answer": "Selecting the winner can also select favorable validation noise.", "explanation": "When many candidates are compared, a winner may owe part of its high validation score to favorable sample variation. Selection therefore creates optimism even if each individual evaluation was honestly performed. An untouched final test set helps measure the selected procedure. The effect becomes relevant when interpreting unusually small differences among competing validation scores.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-can-the-best-validation-score-be-too-favorable"}, {"id": "R-058", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "When can a simple train/test split suffice?", "answer": "When evaluating one predetermined procedure without using the test set for selection.", "explanation": "A simple train/test split can evaluate a procedure that was specified in advance. The model learns on training cases and is scored once on independent test cases. If the test score instead determines which settings or model family to choose, it has become part of selection and a further independent evaluation is needed.", "links": [], "objective": "when-can-a-simple-train-test-split-suffice"}, {"id": "R-060", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is systematic rotation splitting?", "answer": "Assign records to sets using a repeating rule.", "explanation": "Systematic rotation assigns successive records to sets using a repeating pattern, such as training, training, validation. This is easy to reproduce but depends on the record order. A repeating cycle in the data can align with the assignment pattern. Check the ordering before assuming each set represents the same kinds of cases.", "links": [], "objective": "what-is-systematic-rotation-splitting"}, {"id": "R-061", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How can systematic splitting fail for periodically ordered data?", "answer": "The repeating split rule can align with the data cycle and isolate particular phases.", "explanation": "If observations repeat by weekday, shift, or machine, a systematic assignment rule can repeatedly send a particular phase into the same set. Evaluation then measures a different composition from training. For example, every third record might always come from one production line. Examine cycles and grouping before using a repeating split rule.", "links": [], "objective": "how-can-systematic-splitting-fail-for-periodically-ordered-data"}, {"id": "R-062", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is stratified splitting?", "answer": "Split within relevant groups to preserve representation.", "explanation": "Stratification divides records within relevant groups so each set retains useful representation of those groups. For classification, groups may be response classes. It can prevent a small class from disappearing from evaluation, but it does not fix all leakage or temporal issues. The split must still reflect how new deployment cases will arise.", "links": [], "objective": "what-is-stratified-splitting"}, {"id": "R-063", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How does k-fold cross-validation work?", "answer": "Rotate validation across k folds while fitting on the other k-1 folds.", "explanation": "Partition the available fitting cases into k folds. For each round, fit on k-1 folds and evaluate on the remaining fold, rotating until every fold has been held out. Combine evaluation results to compare specifications. Learned preprocessing must be fitted separately within each round, because its held-out fold is evaluation data for that fit.", "links": [], "objective": "how-does-k-fold-cross-validation-work"}, {"id": "R-064", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "How often is a case used in k-fold CV?", "answer": "Validation once; training k-1 times.", "explanation": "In ordinary k-fold cross-validation, each case appears in validation once and in training during the other k-1 rounds. For five folds, that means one validation use and four training uses. This rotates evaluation coverage; it does not mean the same case is simultaneously allowed to influence the fit being used to evaluate it.", "links": [], "objective": "how-often-is-a-case-used-in-k-fold-cv"}, {"id": "R-065", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What should be refit after CV selects a specification?", "answer": "The chosen specification, using all non-test observations.", "explanation": "After cross-validation selects a specification, fit that specification on all available non-test observations to obtain the model intended for use. The fold fits were tools for selection, each trained on only part of the data. Keep the final test set untouched so it can evaluate this refitted, selected procedure independently.", "links": [], "objective": "what-should-be-refit-after-cv-selects-a-specification"}, {"id": "R-066", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why not simply average fold coefficients after selecting a model?", "answer": "Cross-validation selects a specification, not a default coefficient-averaging estimator.", "explanation": "Fold coefficients come from different training subsets and may include different fitted preprocessing. Cross-validation ordinarily selects the model specification rather than defining an estimator by averaging those coefficients. Refit the chosen procedure on all non-test data. Combining models can be a separate modeling decision, but it is not automatically the final step of cross-validation.", "links": [], "objective": "why-not-simply-average-fold-coefficients-after-selecting-a-model"}, {"id": "R-067", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What must happen to preprocessing inside CV?", "answer": "Fit learned preprocessing on each training fold and apply it to its validation fold.", "explanation": "Within each fold, estimate scaling means, ranges, PCA loadings, or other learned transformations from that fold's training portion. Apply those fitted transformations to its validation portion. Computing them once from all cases lets validation information influence its own representation. Treat preprocessing and the model as one procedure that must respect the same evaluation boundary.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-must-happen-to-preprocessing-inside-cv"}, {"id": "R-068", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is data leakage?", "answer": "Using information that should be unavailable during training or decision-making.", "explanation": "Leakage occurs when fitting or decision-making uses information unavailable in the intended prediction setting. It can arise through future variables, shared entities, preprocessing, or selection. For example, a recorded outcome after shipment completion cannot legitimately predict an on-time delivery decision made at dispatch. High measured performance does not repair that information mismatch.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-is-data-leakage"}, {"id": "R-069", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why use chronological validation for forecasts?", "answer": "Future information should not enter a model predicting from the past.", "explanation": "A forecast must use information available before the future response occurs. Chronological evaluation fits on earlier data and evaluates later cases to imitate that condition. Random splitting can mix future patterns into a past prediction. Preserve time order in both model fitting and learned preprocessing when evaluating the forecasting procedure.", "links": [], "objective": "why-use-chronological-validation-for-forecasts"}, {"id": "R-070", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "When should evaluation separate entire entities rather than individual rows?", "answer": "When deployment targets unseen entities and related rows share entity-specific information.", "explanation": "Rows from one customer, device, or subject can share distinctive information. If deployment involves unseen entities, placing related rows in both training and validation can overstate performance. Hold out complete entities to evaluate that task. A row-level split may answer a different question: prediction for entities already partly represented during training.", "links": [], "objective": "when-should-evaluation-separate-entire-entities-rather-than-individual-rows"}, {"id": "R-071", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "What is missing when a relevant deployment subgroup is absent from validation?", "answer": "A subgroup absent from validation cannot provide reliable evidence for that subgroup's deployment.", "explanation": "A validation set cannot measure performance for a subgroup it does not contain. An excellent aggregate score therefore provides little direct evidence about an absent operating regime or population. Check coverage against deployment requirements. Representation matters alongside sample size, because many observations from other groups do not replace evidence about the missing group.", "links": [], "objective": "what-is-missing-when-a-relevant-deployment-subgroup-is-absent-from-validation"}, {"id": "R-072", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why is no split fraction universally best?", "answer": "Sample size, representativeness, and the intended use differ.", "explanation": "A larger training share can improve fitting, while a larger evaluation share can improve the precision of performance estimates. The useful balance depends on sample size, complexity, class frequencies, grouping, and deployment conditions. A fixed percentage does not address every task. Choose a split design that supports both learning and credible evaluation.", "links": [], "objective": "why-is-no-split-fraction-universally-best"}, {"id": "R-073", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why must the validation metric match the intended decision?", "answer": "The best statistical score need not give the best decision value.", "explanation": "A metric determines which mistakes or outcomes are rewarded during selection. Accuracy, squared error, and expected cost answer different questions. If missing a rare failure is expensive, the most accurate classifier may not minimize loss. Select and evaluate using a measure that reflects how model outputs will support the actual decision.", "links": [], "objective": "why-must-the-validation-metric-match-the-intended-decision"}, {"id": "R-074", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "stem": "Why does a final test estimate still have uncertainty?", "answer": "A finite test sample varies and may not represent every deployment condition.", "explanation": "Test performance is an estimate based on a finite collection of cases. Another sample can produce a different score, and deployment may include conditions not represented in the test set. An untouched test set improves independence, but does not remove sampling variation or population mismatch. Interpret small score differences and subgroup claims accordingly.", "links": [], "objective": "why-does-a-final-test-estimate-still-have-uncertainty"}, {"id": "C-007", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "fixed-versus-learned-conversion", "stem": "How does a fixed known unit conversion differ from learned preprocessing?", "answer": "A known conversion estimates nothing from held-out data; learned means, scales, loadings, or selections must respect training boundaries.", "explanation": "A predetermined conversion such as centimeters to meters uses a known rule rather than learning from the held-out sample. Standardization means, PCA directions, or feature selections are different: their values depend on observations. Those learned steps must be fitted inside training boundaries. The distinction concerns information use, not whether both operations are called preprocessing.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-008", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "unequal-fold-aggregation", "stem": "How does pooled validation error differ from equally averaged fold error?", "answer": "Pooling weights each case equally; an equal-fold average weights each fold equally.", "explanation": "An equal average of fold errors gives every fold the same influence, even when fold sizes differ. Pooled error totals mistakes or losses across cases before dividing by the number of cases. For example, folds with 10 and 90 cases receive equal weight in the first approach, but 10% and 90% weight in the second.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-009", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "comparable-performance-evidence", "stem": "What makes two model performance scores meaningfully comparable?", "answer": "Comparable representative evaluation cases and the same relevant error or decision metric.", "explanation": "Scores can be compared meaningfully when they use comparable representative cases, the same response definition, and the same relevant metric. Otherwise the difference may reflect evaluation composition rather than model quality. For example, raw errors measured in different units cannot establish a winner. Check the evaluation conditions before interpreting a larger or smaller score.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-010", "module": 3, "topic": "Validation and selection", "kind": "concept", "source": "Concept", "objective": "underfit-overfit-diagnostic-contrast", "stem": "What error pattern suggests underfitting versus overfitting?", "answer": "Underfitting: poor training and validation fit. Overfitting: strong training fit but weak validation fit.", "explanation": "Poor training and validation fit can indicate that the procedure misses important structure. Strong training fit with much weaker validation fit can indicate overfitting. These are diagnostic patterns, not automatic proofs: mismatched populations, leakage, or an unsuitable metric can complicate them. Investigate the design before choosing a remedy solely from the score gap.", "links": [{"label": "StatQuest cross-validation video", "url": "https://youtu.be/fSytzGwwBVw"}, {"label": "ISLR resampling resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-075", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What does clustering discover?", "answer": "Groups of observations similar under the chosen representation.", "explanation": "Clustering groups observations using similarity in the selected features and distance rule. It does not learn known response classes. A group may describe a useful segment, but its meaning must be interpreted in context. Changing scaling, included variables, or the number of clusters can change the groups, because those choices define what similar means.", "links": [], "objective": "what-does-clustering-discover"}, {"id": "R-076", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Euclidean/L2 distance?", "answer": "Straight-line distance: square root of summed squared coordinate differences.", "explanation": "Euclidean distance is sqrt(sum((x_j-z_j)^2)), the straight-line distance in the represented coordinates. For coordinate differences of 3 and 4, it equals 5. Larger differences receive stronger influence before the square root. Units and scaling therefore matter: a numerically large feature can dominate even when it is not operationally most important.", "links": [], "objective": "what-is-euclidean-l2-distance"}, {"id": "R-077", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Manhattan/L1 distance?", "answer": "Sum of absolute coordinate differences.", "explanation": "Manhattan distance sums absolute coordinate differences, so differences of 3 and 4 give distance 7. It corresponds to adding movement along separate coordinate directions rather than taking a straight diagonal. This can represent grid travel or sequential effort. The interpretation still depends on whether coordinate units and feature weights reflect the actual task.", "links": [], "objective": "what-is-manhattan-l1-distance"}, {"id": "R-078", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is infinity-norm distance?", "answer": "The largest absolute coordinate difference.", "explanation": "Infinity-norm distance uses the largest absolute coordinate difference. Differences of 3 and 4 therefore give distance 4. It can represent an operation limited by the longest of simultaneous requirements, rather than their sum. It ignores smaller coordinate gaps once the maximum is fixed, so choose it only when that behavior fits the similarity question.", "links": [], "objective": "what-is-infinity-norm-distance"}, {"id": "R-079", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is Minkowski distance of order p?", "answer": "(Sum of absolute coordinate differences raised to p) raised to 1/p.", "explanation": "Minkowski distance combines coordinate differences as (sum(abs(x_j-z_j)^p))^(1/p), ordinarily for p>=1. At p=1 it gives Manhattan distance; p=2 gives Euclidean distance; very large p approaches the maximum-coordinate distance. The chosen order changes which gaps dominate, so it is a modeling choice rather than merely a notation change.", "links": [], "objective": "what-is-minkowski-distance-of-order-p"}, {"id": "R-080", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What makes feature weighting meaningful in distance calculations?", "answer": "Weights must represent relevant similarity rather than arbitrary units.", "explanation": "Feature weights determine how differences in each attribute influence similarity. They should represent the task rather than accidental measurement units. For example, a change in travel time may matter more than a change in an unrelated administrative field. Scaling and weighting can improve geometry, but arbitrary weights can make clustering answer an unintended question.", "links": [], "objective": "what-makes-feature-weighting-meaningful-in-distance-calculations"}, {"id": "R-081", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What are the four basic steps of k-means?", "answer": "Initialize centers; assign to nearest centers; update means; repeat.", "explanation": "Choose k initial centers, assign each observation to its nearest center, replace each center with the mean of its assigned observations, and repeat. Assignment and mean updates work together toward the squared-distance objective. Stop when the specified convergence condition is met. Different initial centers can lead to different final groups.", "links": [], "objective": "what-are-the-four-basic-steps-of-k-means"}, {"id": "R-082", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What objective does standard Euclidean k-means minimize?", "answer": "Within-cluster sum of squared distances to the centers.", "explanation": "Standard Euclidean k-means minimizes the sum of squared distances between observations and their assigned centers. Each center is the mean of its cluster because that mean minimizes the squared-distance sum for fixed membership. The objective measures compactness in the chosen coordinates. It does not automatically measure service quality, class separation, or geographic travel time.", "links": [], "objective": "what-objective-does-standard-euclidean-k-means-minimize"}, {"id": "R-083", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why distinguish squared distances from unsquared distances in k-means?", "answer": "The mean minimizes the squared-distance objective, not every possible distance objective.", "explanation": "Squaring distances changes the optimization problem and gives the arithmetic mean its role as the best center for fixed assignments. The same center update is not justified for every distance objective. A different metric may require a different representative. Therefore changing the distance rule while retaining mean updates should not be assumed to preserve standard k-means guarantees.", "links": [], "objective": "why-distinguish-squared-distances-from-unsquared-distances-in-k-means"}, {"id": "R-084", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is a centroid?", "answer": "The mean coordinates of a cluster's assigned observations.", "explanation": "A centroid is formed by taking the mean of each feature across the assigned observations. It need not coincide with an actual data point. For example, two locations at coordinates (0,0) and (4,2) have centroid (2,1). Its usefulness depends on whether averaging those coordinates provides a meaningful representative for the task.", "links": [], "objective": "what-is-a-centroid"}, {"id": "R-085", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why is k-means a heuristic?", "answer": "Different initial centers can lead to different local solutions.", "explanation": "K-means improves an objective through local assignment and update steps rather than searching every possible partition. Consequently it can settle at a local solution determined partly by initialization. A completed run is not proof of the globally smallest WSS. Comparing several starts is a practical way to reduce dependence on a poor initial configuration.", "links": [], "objective": "why-is-k-means-a-heuristic"}, {"id": "R-086", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What does repeated initialization accomplish in k-means?", "answer": "It helps find a better solution at the same k.", "explanation": "Repeated starts fit k-means from different initial centers while keeping k, the observations, and the geometry fixed. Compare the resulting WSS values and retain a better solution under that objective. This addresses local-solution sensitivity. It does not by itself select k or establish that the clusters serve the intended operational purpose.", "links": [], "objective": "what-does-repeated-initialization-accomplish-in-k-means"}, {"id": "R-087", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why should WSS not increase within a standard exact k-means iteration?", "answer": "Each assignment or mean update minimizes its part of the same objective.", "explanation": "With centers fixed, nearest-center assignments minimize each observation's squared-distance contribution. With assignments fixed, taking cluster means minimizes the center contribution. Thus each exact step cannot increase the same WSS objective. This reasoning assumes the ordinary algorithm and appropriate handling of empty clusters; it does not imply every run reaches the global optimum.", "links": [], "objective": "why-should-wss-not-increase-within-a-standard-exact-k-means-iteration"}, {"id": "R-088", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why does selecting k by minimum raw WSS alone fail?", "answer": "More clusters reduce WSS, even when the groups are not useful.", "explanation": "Adding centers provides more flexibility to place observations close to a center, so raw WSS favors increasingly many groups. With one center per observation, WSS can reach zero without providing useful segmentation. Choosing k therefore requires considering diminishing returns, stability, interpretability, or operational constraints instead of simply minimizing unpenalized WSS.", "links": [], "objective": "why-does-selecting-k-by-minimum-raw-wss-alone-fail"}, {"id": "R-089", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is the elbow method?", "answer": "Look for where added clusters give much smaller improvements.", "explanation": "The elbow method plots WSS against k and looks for a transition from large improvements to smaller incremental gains. The bend suggests a compromise between compactness and additional groups. It is a heuristic, and some data have no clear elbow. Inspect the geometry and practical use rather than treating the plot as an automatic unique answer.", "links": [], "objective": "what-is-the-elbow-method", "diagram": "elbow"}, {"id": "R-090", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why can observed WSS from different heuristic runs fail to decrease monotonically with k?", "answer": "Different runs can stop at different local solutions.", "explanation": "The best achievable WSS cannot increase when additional centers are allowed, but separate heuristic runs may land at differently good local solutions. A poorly initialized larger-k run can therefore score worse than a better smaller-k run. Repeat starts and keep data preparation fixed before interpreting an unexpected increase as a property of clustering itself.", "links": [], "objective": "why-can-observed-wss-from-different-heuristic-runs-fail-to-decrease-monotonically-with-k"}, {"id": "R-091", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How does k-means assign a new point?", "answer": "Assign it to the nearest learned center.", "explanation": "Once k-means centers are fitted, a new point is assigned to the closest center in the same prepared coordinates. No class labels are required for this assignment. The point can still be far from every center, so nearest membership alone is not evidence that it resembles ordinary training members or belongs to the training population.", "links": [], "objective": "how-does-k-means-assign-a-new-point"}, {"id": "R-092", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "What is a Voronoi diagram?", "answer": "Regions whose points are closest to each respective center.", "explanation": "A Voronoi diagram partitions space according to which center is nearest under the chosen distance. Each region contains all points assigned to that center by the nearest-center rule. Boundaries correspond to ties between centers. This geometric partition helps visualize assignments, but does not indicate that every location within a region has high data density.", "links": [], "objective": "what-is-a-voronoi-diagram"}, {"id": "R-093", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why is a distant nearest-center assignment not proof of a typical member?", "answer": "Nearest does not necessarily mean close enough or typical.", "explanation": "Nearest is a comparison among available centers, rather than a statement of absolute similarity. A new point very far from all clusters still has a closest center. Inspect its actual distance and context before treating it as typical. The assigned group can be mathematically defined while the case remains unusual relative to the fitted data.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-a-distant-nearest-center-assignment-not-proof-of-a-typical-member"}, {"id": "R-094", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How do outliers affect k-means?", "answer": "They can pull the mean centers.", "explanation": "Means are sensitive to extreme coordinates, and k-means squares distances in its objective. An outlier can therefore pull a center away from the main concentration of cases or attract its own cluster. Investigate whether the point is an error or a valid rare case. Removing it simply to improve compactness can discard important information.", "links": [], "objective": "how-do-outliers-affect-k-means"}, {"id": "R-095", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "When can separate clusterings by operating context be useful?", "answer": "When relevant similarity patterns differ across contexts that support separate decisions.", "explanation": "Different operating contexts can have different notions of ordinary similarity. Separate clusterings can be useful if those contexts support distinct decisions and contain enough relevant observations. For example, day and night usage patterns may group differently. The separation should reflect a justified task, rather than being introduced only to obtain a preferred grouping.", "links": [], "objective": "when-can-separate-clusterings-by-operating-context-be-useful", "diagram": "clusters"}, {"id": "R-096", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How can a facility budget affect k?", "answer": "It limits the number of feasible facilities or service groups.", "explanation": "When centers represent facilities or service groups, k can have a direct resource consequence. A budget may limit how many facilities are feasible, while service requirements constrain acceptable distances or capacities. Pure geometric compactness does not include all those constraints. Use clustering as an input to the decision and check whether the proposed centers are operationally feasible.", "links": [], "objective": "how-can-a-facility-budget-affect-k"}, {"id": "R-097", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Why might direct geographic distance misrepresent travel?", "answer": "Roads, barriers, and travel constraints can change actual access time.", "explanation": "Straight-line geographic distance ignores roads, bridges, barriers, traffic, and restrictions. Two nearby coordinates can require a long journey, while a highway can connect more distant points efficiently. If the purpose is travel or delivery, choose a representation tied to access or travel effort rather than assuming Euclidean proximity provides the relevant service metric.", "links": [], "objective": "why-might-direct-geographic-distance-misrepresent-travel"}, {"id": "R-098", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "Does changing cluster label names change the solution?", "answer": "No. Memberships, centers, and WSS are unchanged.", "explanation": "Cluster labels are arbitrary names attached to groups. Renaming cluster 1 as cluster 3 changes neither its assigned observations nor its center. A comparison should align memberships and centers rather than treating label numbers as ordered measurements. The same partition can appear to have different labels after a repeated fit without being substantively different.", "links": [], "objective": "does-changing-cluster-label-names-change-the-solution"}, {"id": "R-099", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "stem": "How do k in k-means,k-NN,and k-fold CV differ?", "answer": "Clusters, neighbors, and validation folds, respectively.", "explanation": "The symbol k has a different procedural role in each method. K-means uses k centers, k-NN consults k nearby training observations, and k-fold validation divides fitting data into k evaluation folds. Increasing one does not imply the same effect as increasing another. Identify what is being counted before reasoning about its tradeoff.", "links": [], "objective": "how-do-k-in-k-means-k-nn-and-k-fold-cv-differ"}, {"id": "C-011", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "kmeans-required-inputs", "stem": "What data and choices define an ordinary k-means fit?", "answer": "Feature observations, a meaningful prepared geometry, the number of centers k, and an initialization policy.", "explanation": "Ordinary k-means needs numeric feature coordinates with meaningful distances, a selected number of clusters, and an initialization policy. It learns the center coordinates and memberships. It does not need known class responses. Geometry, units, and feature preparation are part of the specification because they determine both assignments and the compactness objective.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-012", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "norm-operational-choice", "stem": "When do L1 and infinity-norm distances match an operational task?", "answer": "L1 adds sequential requirements; infinity norm uses the longest simultaneous requirement.", "explanation": "L1 adds coordinate requirements, which fits a task where separate movements or efforts occur sequentially. Infinity norm takes the largest requirement, which can fit simultaneous processes completed only when the slowest finishes. Differences of 3 and 4 give 7 or 4 respectively. Choose the interpretation that matches the operation rather than automatically choosing Euclidean distance.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-013", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "implicit-row-weight", "stem": "How do duplicate rows affect standard k-means?", "answer": "They contribute repeatedly to the objective and can pull centers toward that location.", "explanation": "Every row contributes to ordinary k-means, even when its coordinates duplicate another row. Repeating a location therefore increases its influence on the squared-distance objective and on assigned cluster means. Distinguish genuine repeated observations from accidental duplication. Deduplicating real cases can also change the intended weighting, so neither operation is automatically neutral.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-014", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "uniform-coordinate-scaling", "stem": "What happens when every Euclidean coordinate is multiplied by the same positive factor a?", "answer": "Relative distances and equivalent memberships are preserved; WSS scales by a squared.", "explanation": "Multiplying all coordinates by the same positive factor multiplies every Euclidean distance by that factor. Relative nearest-center comparisons are unchanged when centers are transformed consistently. Squared distances and WSS multiply by the factor squared. This differs from scaling only one feature, which changes relative geometry and can alter the grouping.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-015", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "case-weight-versus-feature-weight", "stem": "How do observation weights differ from feature weights in clustering?", "answer": "Observation weights emphasize cases; feature weights define which coordinate differences count more.", "explanation": "Observation weights change how much particular cases contribute to an objective or center calculation. Feature weights change the importance of coordinate differences and therefore the geometry of similarity. Giving one customer more influence is not the same as giving delivery distance more importance. Identify whether the weighting represents cases or attributes before interpreting its effect.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-016", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "empty-cluster-mean", "stem": "Why does an empty k-means cluster need an explicit handling rule?", "answer": "No assigned observations means its ordinary mean is undefined.", "explanation": "The mean center update requires assigned observations. If none are assigned, dividing by the cluster size is undefined. An implementation needs a policy such as repositioning the center or another explicit rule. Empty clusters do not automatically justify silently changing k; the handling should be consistent with the intended fitting procedure and comparison.", "links": [{"label": "StatQuest k-means video", "url": "https://youtu.be/4b5d3muPQmA"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-017", "module": 4, "topic": "Clustering and distance", "kind": "concept", "source": "Concept", "objective": "wss-comparability", "stem": "Why should WSS comparisons hold the data and geometry fixed?", "answer": "Changing rows, units, or feature weights changes the objective scale and the problem being measured.", "explanation": "WSS depends on the number of contributing cases and their coordinate units and weights. A lower score after changing any of these may reflect a different objective scale instead of better grouping. Compare runs on the same prepared observations and geometry. For example, converting every coordinate to a smaller unit factor changes WSS without changing memberships.", "links": []}, {"id": "R-100", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a point outlier?", "answer": "An individually unusual observation.", "explanation": "A point outlier is an individual observation unusual relative to the comparison population or model. An unusually large recorded transaction may be one example. The flag describes unusualness, not its cause or validity. Investigate whether it reflects an error, a real rare event, or a case whose relevant context has not been represented.", "links": [], "objective": "what-is-a-point-outlier"}, {"id": "R-101", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a contextual outlier?", "answer": "An observation unusual for its time, place, or other context.", "explanation": "A contextual outlier is unusual only after accounting for circumstances such as season, location, or operating state. A temperature normal in summer may be unusual in winter. A global threshold can miss this distinction. Compare the observation with an appropriate contextual expectation before deciding whether it is anomalous.", "links": [], "objective": "what-is-a-contextual-outlier"}, {"id": "R-102", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What is a collective outlier?", "answer": "An unusual group or sequence, even if individual values look normal.", "explanation": "A collective outlier is an unusual collection, pattern, or sequence whose individual values may each look ordinary. Repeated moderate readings in an unexpected order can be suspicious even when no reading is extreme. Detecting it requires representing the relationship among observations, rather than examining each value independently against a simple point threshold.", "links": [], "objective": "what-is-a-collective-outlier"}, {"id": "R-103", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "How can representation turn a collective anomaly into a point anomaly?", "answer": "Represent event gaps as intervals; an unusual missing event can become one extreme gap.", "explanation": "An unusual sequence can sometimes be represented as a single unusual derived measurement. For example, a missing regular event produces a long interval between neighboring events. That interval may be a point outlier even though the original issue involved a sequence. Representation changes what the detector sees, so define the derived variable carefully.", "links": [], "objective": "how-can-representation-turn-a-collective-anomaly-into-a-point-anomaly"}, {"id": "R-104", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What does an outlier flag from a boxplot establish?", "answer": "The value is unusual under that rule, not necessarily incorrect or suitable for deletion.", "explanation": "A boxplot flag identifies a value beyond a chosen spread-based rule, commonly one involving the interquartile range. It does not establish that the measurement is wrong. Genuine tail events can be important to the task. Investigate provenance, context, and intended population before deciding to correct, keep, separately model, or exclude the flagged record.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-an-outlier-flag-from-a-boxplot-establish"}, {"id": "R-106", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why can model residuals help find contextual anomalies?", "answer": "They expose deviations from the expected response for a case's context.", "explanation": "A residual compares the observed response with the fitted expectation for that case's predictors. It can highlight an observation that is globally ordinary but unusual for its context. For example, moderate energy use can be unexpectedly high for an empty building. The baseline model must represent relevant context well enough for this comparison to be meaningful.", "links": [], "objective": "why-can-model-residuals-help-find-contextual-anomalies"}, {"id": "R-107", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What should be investigated before excluding an outlier?", "answer": "Its validity, origin, and relevance to the intended population.", "explanation": "Check whether the measurement is accurate, how it was produced, and whether the case belongs to the population being modeled. An entry mistake may warrant correction, while a genuine rare failure may need retention. Document the reason for any exclusion. Unusualness or a better fitted score alone is not enough to determine the appropriate treatment.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-should-be-investigated-before-excluding-an-outlier"}, {"id": "R-108", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "What distinguishes a real rare event from a data error?", "answer": "A rare event is genuine; a data error misrepresents what happened.", "explanation": "A real rare event accurately records something unusual that occurred. A data error gives an incorrect account, such as a misplaced decimal or a faulty sensor reading. Their numerical appearances can be similar. Use source information and context to distinguish them, because deleting real events can harm modeling while retaining errors can distort it.", "links": [], "objective": "what-distinguishes-a-real-rare-event-from-a-data-error"}, {"id": "R-109", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why can deleting genuine tail events harm risk modeling?", "answer": "Rare but real events may dominate the losses the model is intended to assess.", "explanation": "Risk analysis often depends strongly on infrequent but consequential outcomes. Removing genuine tail events can make the modeled process look safer than it is. A lower average error after deletion may therefore conflict with the actual objective. Preserve relevant rare events or model their regime explicitly rather than treating all extremes as nuisances.", "links": [], "objective": "why-can-deleting-genuine-tail-events-harm-risk-modeling"}, {"id": "R-110", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "How can separate models handle ordinary and rare-event behavior?", "answer": "Separate regimes can preserve different behavior instead of forcing one common model.", "explanation": "One model may describe ordinary operations poorly when rare events arise through a different process. Separate regime models can represent each behavior while preserving the important events. This requires a justified regime definition and an appropriate way to use the models. Splitting cases solely to obtain a more attractive fit does not establish that the distinction is valid.", "links": [], "objective": "how-can-separate-models-handle-ordinary-and-rare-event-behavior"}, {"id": "R-111", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "When can excluding a valid unusual event be justified?", "answer": "When it is outside the clearly defined target population and the restriction is disclosed.", "explanation": "A valid observation can be irrelevant to a narrowly defined target population. For example, a special emergency operation may fall outside a model explicitly intended for routine operations. Exclusion should follow that definition and be disclosed. It should not be chosen merely because the observation makes the fit worse or contradicts a preferred conclusion.", "links": [], "objective": "when-can-excluding-a-valid-unusual-event-be-justified"}, {"id": "R-112", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Does a better fitted score after deleting an outlier prove that the record was invalid?", "answer": "An improved fit is not proof that a flagged record is invalid.", "explanation": "Removing a difficult observation usually makes fitting easier, whether that observation was an error or a legitimate rare case. An improved score therefore cannot establish invalidity. Investigate the record independently and relate the decision to the intended population. Otherwise the procedure can selectively erase precisely the cases its predictions need to handle.", "links": [], "objective": "does-a-better-fitted-score-after-deleting-an-outlier-prove-that-the-record-was-invalid"}, {"id": "R-114", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "stem": "Why do large datasets naturally contain some extreme normal observations?", "answer": "Extreme but genuine values become more likely as the number of observations grows.", "explanation": "Even a well-behaved distribution assigns some probability to far-tail outcomes. As more observations are collected, there are more opportunities to encounter them. Thus a large dataset can contain genuinely extreme cases without a data-quality problem. Interpret flags in light of sample size, context, and the detection rule rather than assuming every extreme value is erroneous.", "links": [], "objective": "why-do-large-datasets-naturally-contain-some-extreme-normal-observations"}, {"id": "C-018", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "joint-anomaly", "stem": "Can ordinary individual feature values form an unusual combination?", "answer": "Yes. Their joint or conditional relationship can be unusual even when each value looks ordinary.", "explanation": "Features can each look ordinary while their combination is unusual. If two measurements usually move together, a high value of one with a low value of the other can be unexpected even though both values occur individually. Joint relationships or contextual residuals can reveal this pattern when separate one-variable thresholds cannot.", "links": []}, {"id": "C-019", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "residual-flag-missing-context", "stem": "Why can repeated residual outlier flags indicate a baseline problem?", "answer": "Missing systematic context can make normal cases repeatedly deviate from the modeled expectation.", "explanation": "Repeated residual flags can mean that the model omitted a systematic factor, rather than that many observations are wrong. For example, a baseline fitted to unoccupied buildings can repeatedly flag ordinary occupied usage. Inspect residuals by relevant regimes and predictors. A better contextual expectation can distinguish normal structure from genuine deviations.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-020", "module": 5, "topic": "Outliers", "kind": "concept", "source": "Concept", "objective": "missing-code-not-measurement", "stem": "How should a known numeric missing-value code be interpreted?", "answer": "As missing information, not as an actual extreme measurement.", "explanation": "A sentinel such as -999 can encode missing information instead of an observed numeric quantity. Treating it as a real coordinate can distort means, scales, distances, and outlier flags. Identify the encoding and use an explicit missing-data policy. The apparent extreme value then reflects representation, not evidence of an extreme underlying measurement.", "links": [{"label": "ISLR linear-model diagnostics and unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-115", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM mean and target?", "answer": "Cumulative sum; it detects sustained changes relative to a baseline.", "explanation": "CUSUM accumulates evidence of directional departures from a reference level over an ordered sequence. Repeated modest deviations can eventually signal a change even when no single reading appears remarkable. Define the baseline, allowance, direction, and threshold before monitoring. An alarm identifies evidence under that specification; it does not explain the cause of the change.", "links": [], "objective": "what-does-cusum-mean-and-target"}, {"id": "R-116", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is the upper CUSUM update?", "answer": "S_new=max(0,S_previous+x-mu-C).", "explanation": "For upper CUSUM, add x-mu-C to the previous statistic and replace a negative result with zero. The deviation x-mu measures upward departure, while C subtracts an allowance. For example, S_previous=2, x=12, mu=10, C=1 gives S_new=3. Compare the accumulated statistic with the separate alarm threshold.", "links": [], "objective": "what-is-the-upper-cusum-update"}, {"id": "R-117", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is a positive-valued lower CUSUM update?", "answer": "S_new=max(0,S_previous+mu-x-C).", "explanation": "A positive-valued lower CUSUM reverses the departure term to mu-x-C, then resets a negative raw total to zero. Low observations can therefore add evidence of downward change. For example, mu=10, x=8, C=1 adds one to the previous statistic. The upward and downward monitors have different directional increments.", "links": [], "objective": "what-is-a-positive-valued-lower-cusum-update"}, {"id": "R-118", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "How can both upward and downward changes be monitored?", "answer": "Use separate upper- and lower-direction monitors.", "explanation": "Maintain separate upper and lower statistics when departures in either direction matter. The upper update accumulates x-mu-C; the positive lower update accumulates mu-x-C. Each can have its own alarm threshold or cost considerations. A single directional monitor does not automatically detect both increases and decreases simply because its inputs vary over time.", "links": [], "objective": "how-can-both-upward-and-downward-changes-be-monitored"}, {"id": "R-119", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's baseline mu represent?", "answer": "The expected level under the reference process.", "explanation": "The baseline mu defines the level expected under the reference process. CUSUM measures departures relative to that level, not relative to every recent observation. An inappropriate baseline can produce misleading alarms. For example, normal changes between occupied and empty operating regimes may appear anomalous if the reference ignores that contextual difference.", "links": [], "objective": "what-does-cusum-s-baseline-mu-represent"}, {"id": "R-120", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's allowance C do?", "answer": "It reduces the contribution of each deviation to accumulated evidence.", "explanation": "The allowance C is subtracted from every directional deviation before accumulation. It reduces sensitivity to small departures and can make a modest sustained shift contribute little or nothing. Increasing C does not move the alarm line; that is the threshold's role. Assess allowance and threshold together against false-alarm and detection-delay consequences.", "links": [], "objective": "what-does-cusum-s-allowance-c-do"}, {"id": "R-121", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What does CUSUM's threshold T do?", "answer": "It sets the accumulated evidence needed for an alarm.", "explanation": "The threshold T is the accumulated-evidence level at which the specified alarm rule fires. A larger threshold generally requires more evidence, potentially delaying detection while reducing alarms. It differs from C, which changes each update. Specify whether crossing means greater than or at least the threshold, because equality can affect a worked calculation.", "links": [], "objective": "what-does-cusum-s-threshold-t-do"}, {"id": "R-122", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Why does upper CUSUM reset negative raw totals to zero?", "answer": "To discard accumulated evidence in the opposite direction.", "explanation": "Negative raw upper-CUSUM totals represent evidence in the opposite direction. Resetting to zero prevents old downward departures from indefinitely masking a later upward shift. The reset operates on the accumulated total, not simply on the sign of the newest deviation. A modest negative increment can reduce a positive total without resetting it.", "links": [], "objective": "why-does-upper-cusum-reset-negative-raw-totals-to-zero"}, {"id": "R-123", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "How does CUSUM use persistent directional deviations?", "answer": "Net directional deviations accumulate, potentially revealing changes that individual readings do not flag.", "explanation": "A succession of positive net deviations can build a large statistic even when individual deviations are modest. This is why CUSUM is useful for sustained shifts rather than only extreme point readings. Accumulation still depends on the allowance: persistent above-baseline readings that do not exceed it need not build upward evidence.", "links": [], "objective": "how-does-cusum-use-persistent-directional-deviations"}, {"id": "R-124", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Can a single extreme observation trigger CUSUM?", "answer": "Yes, if its contribution makes the statistic cross the threshold.", "explanation": "Although CUSUM is useful for persistent change, one sufficiently extreme reading can add enough evidence to cross the alarm threshold immediately. Persistence is not a requirement built into every alarm. Check the actual update and prior total. An alarm can result from a large single contribution, multiple smaller contributions, or both.", "links": [], "objective": "can-a-single-extreme-observation-trigger-cusum"}, {"id": "R-125", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What costs guide CUSUM tuning?", "answer": "False-alarm consequences and delayed or missed detection.", "explanation": "A sensitive monitor can react quickly but generate costly false alarms. A conservative monitor can reduce alarms while delaying response to real changes. Choose settings with those consequences in mind rather than optimizing one in isolation. The baseline, allowance, threshold, and operating population all affect whether the resulting tradeoff serves the task.", "links": [], "objective": "what-costs-guide-cusum-tuning"}, {"id": "R-126", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What is a CUSUM control chart?", "answer": "A plot of the accumulated statistic against its alarm threshold over the index.", "explanation": "A CUSUM chart shows the accumulated statistic against the observation index and the chosen alarm threshold. It is different from a plot of raw measurements. Rising segments show accumulating directional evidence, while resets discard opposing evidence. Interpret the curve using its baseline and update convention, because its height is not directly the raw process level.", "links": [], "objective": "what-is-a-cusum-control-chart"}, {"id": "R-128", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "What makes change-detection reporting defensible?", "answer": "Disclose definitions and settings, and report supported conclusions instead of choosing a preferred result.", "explanation": "Report the reference, update convention, settings, and what the resulting alarm supports. Changing these after seeing the data can create a preferred story rather than a defensible analysis. Detection establishes a departure under the chosen rule, not causality. Explain relevant limitations and avoid presenting a tuned signal as independent proof of an operational claim.", "links": [], "objective": "what-makes-change-detection-reporting-defensible"}, {"id": "R-129", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "stem": "Why does a later end date alone not establish a longer period?", "answer": "Duration depends on both start and end; either boundary may change.", "explanation": "A duration is the difference between its end and start. A later end date alone does not imply a longer interval if the start also moves later. For example, a period ending in June can be shorter than one ending in May. Compare both boundaries before interpreting a change in monitored period length.", "links": [], "objective": "why-does-a-later-end-date-alone-not-establish-a-longer-period"}, {"id": "C-021", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "allowance-blocks-departure", "stem": "Can a sustained above-baseline shift fail to accumulate in upper CUSUM?", "answer": "Yes. If the departure is smaller than the allowance, net increments may stay nonpositive.", "explanation": "An upper monitor adds x-mu-C, rather than x-mu alone. If a sustained departure is smaller than C, its deterministic contribution remains nonpositive and can be discarded by resets. For example, a one-unit departure with a two-unit allowance does not accumulate upward evidence from those constant readings. Random fluctuation can still affect the realized sequence.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "C-022", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "negative-increment-versus-reset", "stem": "Does one below-baseline reading necessarily reset an upper CUSUM?", "answer": "No. A negative increment reduces the total; reset occurs only when the raw updated total is nonpositive.", "explanation": "Resetting depends on the new accumulated total. If the previous statistic is ten and the next increment is minus two, the new value is eight, not zero. Only a nonpositive raw total is replaced by zero in the stated update. Distinguish a downward contribution from complete loss of previously accumulated evidence.", "links": []}, {"id": "C-023", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "statistic-versus-shift-size", "stem": "Why is a CUSUM statistic not the estimated mean-shift magnitude?", "answer": "It accumulates successive net deviations, rather than directly estimating a single level change.", "explanation": "CUSUM sums net departures across observations, so its height depends on both their sizes and the sequential path. Repeated small departures can produce the same total as a larger isolated departure. It is therefore a detection statistic rather than a direct estimate of the new mean minus the old mean. Do not interpret its units as a shift estimate.", "links": []}, {"id": "C-024", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "reference-regime-suitability", "stem": "Why must a change monitor's reference match the intended operating regime?", "answer": "Normal differences between regimes can appear as departures from an inappropriate reference.", "explanation": "The reference should represent the operating condition under which a departure is considered unusual. Normal differences between shifts, seasons, or occupancy states can otherwise create false interpretations. A monitor anchored to empty operation may alarm during ordinary occupied operation. Define the intended regime or account for predictable differences before attributing every signal to deterioration.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "C-025", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "cusum-sequence-order", "stem": "Why does observation order matter to reset-to-zero CUSUM?", "answer": "Accumulation and resets depend on the sequential path, so shuffling can change alarm timing.", "explanation": "CUSUM resets depend on the order of increments, so the same collection of readings can yield different paths after shuffling. Negative evidence occurring first may be discarded, while the same evidence later may reduce a positive accumulated total. Alarm timing consequently depends on the sequence, not just the sum or average of all observations.", "links": []}, {"id": "C-026", "module": 6, "topic": "Change detection", "kind": "concept", "source": "Concept", "objective": "cusum-unit-consistency", "stem": "What must stay compatible when changing a CUSUM measurement scale?", "answer": "Transform the reference and scale the allowance and threshold consistently with response differences.", "explanation": "A unit conversion must transform the monitored values and baseline consistently. For a positive scaling factor, the deviations, allowance, and threshold scale by that factor; a common offset cancels in x-mu. Converting the measurements while leaving settings in the old units changes the monitoring rule and can alter alarms for purely representational reasons.", "links": [{"label": "NIST CUSUM explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section3/pmc323.htm"}]}, {"id": "R-130", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What are the components considered in exponential smoothing?", "answer": "Level, trend, and seasonality, depending on the specification.", "explanation": "Exponential-smoothing specifications can represent a current level, a directional trend, and a repeating seasonal effect. Single smoothing uses level alone; Holt adds trend; Holt-Winters also includes seasonality. Select components that suit the observed temporal structure. Adding a component introduces fitting choices and does not automatically improve held-out forecasts.", "links": [], "objective": "what-are-the-components-considered-in-exponential-smoothing"}, {"id": "R-131", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the single exponential-smoothing update?", "answer": "S_t=alpha*x_t+(1-alpha)*S_(t-1).", "explanation": "The update blends the newest observation with the previous smoothed level: S_t=alpha*x_t+(1-alpha)*S_(t-1). The previous level summarizes earlier history. For example, alpha=0.2, x_t=120, and S_(t-1)=100 give S_t=104. This is a level estimate using the current observation, rather than an advance forecast made before observing it.", "links": [], "objective": "what-is-the-single-exponential-smoothing-update"}, {"id": "R-132", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How does alpha control smoothing?", "answer": "Larger alpha gives more weight to the newest observation.", "explanation": "Alpha determines how strongly the current observation changes the smoothed level. A larger value adapts faster to recent changes but also follows more short-term noise. A smaller value retains more influence from past estimates and reacts more slowly. Choose the tradeoff using relevant forecast performance rather than treating rapid response as universally better.", "links": [], "objective": "how-does-alpha-control-smoothing"}, {"id": "R-133", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What happens at alpha=1 and alpha=0?", "answer": "Alpha=1 uses the latest observation; alpha=0 retains the initial level.", "explanation": "At alpha=1, the previous estimate receives zero weight and the new level equals the latest observation. At alpha=0, every new observation receives zero weight and the initialized level remains unchanged. These endpoints illustrate the adaptation tradeoff. Intermediate weights combine new information with past history instead of choosing either extreme behavior.", "links": [], "objective": "what-happens-at-alpha-1-and-alpha-0"}, {"id": "R-134", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why is smoothing called exponential?", "answer": "Older observations receive exponentially declining weights.", "explanation": "Repeatedly expanding the level recursion gives earlier observations weights proportional to alpha*(1-alpha)^j, where j counts how far back they occurred. These weights decline geometrically with age. The method therefore retains older information with diminishing influence, rather than averaging a fixed recent window and abruptly discarding everything outside it.", "links": [], "objective": "why-is-smoothing-called-exponential"}, {"id": "R-136", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the single-smoothing h-step point forecast?", "answer": "The latest level at every ordinary point-forecast horizon.", "explanation": "Single exponential smoothing has no trend or seasonal component to extend into the future. Its ordinary point forecast is therefore the latest level for every horizon. This does not imply future outcomes are certain or identical. It means the model's best level estimate remains unchanged until another observation provides new information.", "links": [], "objective": "what-is-the-single-smoothing-h-step-point-forecast"}, {"id": "R-137", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a simple starting level for exponential smoothing?", "answer": "The first observed response value.", "explanation": "Using the first observed response as the initial level provides a simple starting value for the recursion. Later observations update that value according to alpha. This initialization is a choice, not a defining requirement of smoothing; initial levels can also be estimated. Early predictions can be especially sensitive to the chosen starting value.", "links": [{"label": "Forecasting textbook: single smoothing", "url": "https://otexts.com/fpp3/ses.html"}], "objective": "what-is-a-simple-starting-level-for-exponential-smoothing"}, {"id": "R-138", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's level update?", "answer": "S_t=alpha*x_t+(1-alpha)*(S_(t-1)+T_(t-1)).", "explanation": "Holt's level update compares the new observation with the previous level projected forward by its trend. It blends x_t with S_(t-1)+T_(t-1), using alpha. This differs from single smoothing, which blends with the previous level alone. Including the projection allows the model to track a moving baseline instead of treating every increase as noise.", "links": [], "objective": "what-is-holt-s-level-update"}, {"id": "R-139", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's trend update?", "answer": "T_t=beta*(S_t-S_(t-1))+(1-beta)*T_(t-1).", "explanation": "Holt updates trend by blending the latest change in smoothed level, S_t-S_(t-1), with the previous trend. Beta controls that blend separately from alpha's level weighting. A large beta makes trend estimates react quickly to recent changes. The trend has units of response change per observation interval, so the interval definition matters.", "links": [], "objective": "what-is-holt-s-trend-update"}, {"id": "R-140", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is Holt's h-step forecast?", "answer": "Current level+h*current trend.", "explanation": "Ordinary Holt forecasts extend the current estimated level by h periods of current trend: S_t+h*T_t. If level is 100 and trend is 3 per observation interval, a four-step forecast is 112. The formula assumes that the current trend is carried forward; it does not incorporate newly observed future responses or a seasonal multiplier.", "links": [], "objective": "what-is-holt-s-h-step-forecast"}, {"id": "R-141", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does initializing a smoothing trend to zero mean?", "answer": "The model starts with no assumed upward or downward change.", "explanation": "An initial trend of zero starts the recursion without assuming systematic upward or downward movement. Subsequent level changes can still update the trend when beta is positive. Zero initialization is simple but not mandatory; a starting trend can instead be estimated from early data. Avoid interpreting the initial value as a claim that the series never trends.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-does-initializing-a-smoothing-trend-to-zero-mean"}, {"id": "R-142", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does seasonal cycle length L mean?", "answer": "The number of observations in one repeating cycle.", "explanation": "L counts observations in one seasonal cycle, not necessarily days or months. Hourly data with daily seasonality use L=24, while daily data with weekly seasonality use L=7. The cycle can also be indexed by repeated production positions. Define the observation interval before selecting a seasonal period or matching a forecast to its phase.", "links": [], "objective": "what-does-seasonal-cycle-length-l-mean"}, {"id": "R-143", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How is a calendar cycle converted into a seasonal observation count?", "answer": "Divide cycle duration by the observation interval when observations are regularly spaced.", "explanation": "For regularly spaced observations, divide the cycle duration by the spacing between observations. A 24-hour cycle with one observation every two hours has L=12. This conversion requires compatible units and regular spacing. If data are indexed by items or events, calendar duration alone may not supply the correct repeating observation count.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "how-is-a-calendar-cycle-converted-into-a-seasonal-observation-count"}, {"id": "R-145", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do multiplicative seasonal factors below, equal to, or above one mean?", "answer": "Below one reduces the baseline; one is neutral; above one increases it.", "explanation": "Multiplicative factors scale the nonseasonal baseline. A factor of 0.8 means 20% below it, 1 leaves it unchanged, and 1.2 means 20% above it. Whether a larger predicted response is operationally favorable depends on the response. For example, more output and more waste have different meanings even when both increase numerically.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-do-multiplicative-seasonal-factors-below-equal-to-or-above-one-mean"}, {"id": "R-147", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How do additive and multiplicative seasonal effects differ?", "answer": "Additive effects are amounts; multiplicative effects are ratios.", "explanation": "Additive seasonality changes the baseline by an amount in response units, while multiplicative seasonality changes it by a ratio. Adding 10 has the same absolute effect at every level; multiplying by 1.1 produces a larger absolute effect at a larger baseline. Choose the representation that matches how seasonal amplitude behaves.", "links": [], "objective": "how-do-additive-and-multiplicative-seasonal-effects-differ"}, {"id": "R-148", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the multiplicative Holt-Winters level update?", "answer": "S_t=alpha*(x_t/C_(t-L))+(1-alpha)*(S_(t-1)+T_(t-1)).", "explanation": "The multiplicative Holt-Winters level update first removes the observation's seasonal effect by dividing x_t by C_(t-L). It blends that deseasonalized value with the prior projected level S_(t-1)+T_(t-1). Alpha controls the level weighting. Using a factor from the same phase keeps the level estimate separate from the repeating seasonal pattern.", "links": [], "objective": "what-is-the-multiplicative-holt-winters-level-update"}, {"id": "R-149", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the multiplicative Holt-Winters seasonal update?", "answer": "C_t=gamma*(x_t/S_t)+(1-gamma)*C_(t-L).", "explanation": "The seasonal update compares the observed value with the current level using x_t/S_t. Gamma blends that ratio with the prior factor for the same phase, C_(t-L). This updates seasonality separately from trend and level. The division requires a suitable nonzero baseline, which is one reason multiplicative formulations need care around zero.", "links": [], "objective": "what-is-the-multiplicative-holt-winters-seasonal-update"}, {"id": "R-150", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does the seasonal update use t-L instead of t-1?", "answer": "It refers to the previous estimate for the same seasonal phase.", "explanation": "Seasonal position repeats after L observations. Thus t-L is the previous occurrence of the current phase, whereas t-1 is the immediately preceding and usually different phase. With monthly data and an annual cycle, a January update uses the prior January factor. Using December's factor instead would mix distinct seasonal effects.", "links": [], "objective": "why-does-the-seasonal-update-use-t-l-instead-of-t-1"}, {"id": "R-151", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a neutral starting multiplicative seasonal factor?", "answer": "One: it leaves the baseline unchanged.", "explanation": "A factor of one is neutral because multiplying any baseline by it leaves the baseline unchanged. It provides a simple initialization with no assumed seasonal departures. The factors can then adapt as observations arrive. Initial factors can also be estimated from historical cycles; neutrality is a starting convention, not a requirement that the actual series lack seasonality.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}], "objective": "what-is-a-neutral-starting-multiplicative-seasonal-factor"}, {"id": "R-152", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is the one-step multiplicative Holt-Winters forecast?", "answer": "(Current level+current trend)*next phase's seasonal factor.", "explanation": "A one-step multiplicative Holt-Winters forecast projects the level forward by one trend increment and applies the seasonal factor for the next phase. The appropriate factor comes from the most recent estimate of that phase. Using the current phase's factor can shift the seasonal pattern, even when the level and trend calculations are correct.", "links": [], "objective": "what-is-the-one-step-multiplicative-holt-winters-forecast"}, {"id": "R-153", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why are zeros or negative values troublesome for multiplicative seasonality?", "answer": "Division and relative-scale effects can become unsuitable or undefined.", "explanation": "Multiplicative seasonality interprets effects as ratios and uses divisions by a level or seasonal factor. A zero denominator is undefined, and signed or near-zero responses can make ratio interpretations unsuitable or unstable. Additive effects or another justified representation may be more appropriate. Do not apply the multiplicative formulas solely because seasonality exists.", "links": [], "objective": "why-are-zeros-or-negative-values-troublesome-for-multiplicative-seasonality"}, {"id": "R-154", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How can smoothing coefficients be selected?", "answer": "Fit them to historical data, then check forecast performance on held-out future observations.", "explanation": "Choose alpha, beta, and gamma where relevant by fitting historical forecasts or another specified training criterion. Then evaluate the chosen forecasting procedure on later held-out observations. Compute a forecast before its target is observed. A coefficient choice that follows historical noise very closely can fit well while producing less reliable future predictions.", "links": [{"label": "Forecasting textbook: single smoothing", "url": "https://otexts.com/fpp3/ses.html"}], "objective": "how-can-smoothing-coefficients-be-selected"}, {"id": "R-155", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why distinguish a smoothed estimate from an advance forecast?", "answer": "A smoothed estimate can use the observation being estimated; an advance forecast cannot.", "explanation": "A smoothed value at time t can incorporate x_t, so it benefits from knowing the observation being summarized. A forecast of x_t made at t-1 cannot use x_t. Comparing these as if both were advance predictions overstates performance. Respect the forecast origin when calculating errors or selecting smoothing settings.", "links": [], "objective": "why-distinguish-a-smoothed-estimate-from-an-advance-forecast"}, {"id": "R-156", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do ARIMA's letters stand for?", "answer": "Autoregressive Integrated Moving Average.", "explanation": "Autoregressive refers to dependence on earlier values of the modeled series. Integrated refers to undoing the differencing used to obtain that series. Moving average refers to dependence on earlier innovations or prediction errors. These components describe temporal structure; the moving-average term is not simply an arithmetic average of recent observed responses.", "links": [], "objective": "what-do-arima-s-letters-stand-for"}, {"id": "R-157", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What do p,d,q mean in ARIMA?", "answer": "Value lags, differencing order, and error lags, respectively.", "explanation": "In ARIMA(p,d,q), p counts lagged values, d gives the differencing order, and q counts lagged errors. If d>0, the lag relationships are modeled in the differenced series. These are structural choices; fitted lag coefficients are separate numerical parameters. For example, ARIMA(1,1,0) uses one lag of first differences and no lagged-error term.", "links": [], "objective": "what-do-p-d-q-mean-in-arima"}, {"id": "R-158", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a first difference?", "answer": "x_t-x_(t-1).", "explanation": "A first difference measures the change between adjacent observations: x_t-x_(t-1). Values 10, 13, and 15 produce differences 3 and 2. Modeling changes can help remove certain level trends. A forecasted difference is an increment, so recovering a forecast on the original scale requires adding it back to the latest level.", "links": [], "objective": "what-is-a-first-difference"}, {"id": "R-159", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is a second difference?", "answer": "The difference between consecutive first differences.", "explanation": "A second difference is the difference between consecutive first differences. Algebraically it is x_t-2*x_(t-1)+x_(t-2). For 10, 13, and 15 it equals 2-3=-1. It is not the two-period change x_t-x_(t-2). Distinguish difference order from how far apart two original observations are.", "links": [], "objective": "what-is-a-second-difference"}, {"id": "R-160", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does ARIMA autoregression use as predictors?", "answer": "Earlier values of the modeled series.", "explanation": "An autoregressive term uses earlier values of the same modeled series as predictors. In an ARIMA model with differencing, those values are earlier differences rather than necessarily the raw levels. This differs from a regression using unrelated external attributes. The lag order determines how many past modeled values enter the temporal relationship.", "links": [], "objective": "what-does-arima-autoregression-use-as-predictors"}, {"id": "R-161", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does the ARIMA moving-average component use?", "answer": "Earlier prediction errors, not a rolling average of response observations.", "explanation": "The moving-average component uses earlier innovations, which are departures from predictions based on available information. Those errors can affect later values through fitted lag coefficients. This meaning of moving average differs from smoothing observations with a rolling arithmetic mean. Distinguish a lagged error from a lagged observed response when reading an ARIMA specification.", "links": [], "objective": "what-does-the-arima-moving-average-component-use"}, {"id": "R-162", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does stationarity mean for a time series?", "answer": "Its statistical behavior, including mean and variability, remains stable over time.", "explanation": "Stationarity describes statistical behavior that stays stable over time. At survey depth, stable mean and variability are central distinctions from a trending or changing-spread series. Differencing can help stabilize some patterns, but is not a universal fix. Inspect the resulting behavior instead of assuming any chosen differencing order automatically produces stationarity.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-does-stationarity-mean-for-a-time-series"}, {"id": "R-163", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is ARIMA(0,0,0) without a constant?", "answer": "White noise: no value lags, differencing, or error lags.", "explanation": "With no constant, ARIMA(0,0,0) has neither lagged values nor lagged errors and applies no differencing. It represents white noise rather than a persistent temporal pattern. A constant can instead establish a fixed mean around which noise varies. Check that convention before assuming that every specification written this way necessarily has mean zero.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-is-arima-0-0-0-without-a-constant"}, {"id": "R-164", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What is ARIMA(0,1,0) without drift?", "answer": "A random walk: the next value equals the previous value plus a random error.", "explanation": "ARIMA(0,1,0) without drift models first differences as white noise. Equivalently, the new level is the previous level plus a random innovation. Its ordinary next-level forecast is the latest observed level. Adding drift changes the mean increment, so the no-drift qualification matters when interpreting this specification as a random walk.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "what-is-arima-0-1-0-without-drift"}, {"id": "R-165", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What are pure AR(p) and MA(q) specifications?", "answer": "ARIMA(p,0,0) and ARIMA(0,0,q), respectively.", "explanation": "A pure AR(p) model uses p lagged values with no differencing or moving-average terms, so it is ARIMA(p,0,0). A pure MA(q) model uses q lagged errors with no differencing or autoregressive terms, so it is ARIMA(0,0,q). The labels describe which temporal inputs enter, not an average of recent responses.", "links": [], "objective": "what-are-pure-ar-p-and-ma-q-specifications"}, {"id": "R-166", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How is simple exponential smoothing related to ARIMA(0,1,1)?", "answer": "ARIMA(0,1,1) without a constant can produce equivalent simple exponential-smoothing forecasts.", "explanation": "Simple exponential smoothing and an appropriately parameterized ARIMA(0,1,1) without a constant can produce equivalent forecasts. This connection shows that different model representations can overlap. Compatible settings and initialization matter: fitting each procedure independently does not guarantee identical results. The connection does not imply that every smoothing model and every ARIMA model are interchangeable.", "links": [{"label": "Forecasting: smoothing and ARIMA", "url": "https://otexts.com/fpp3/arima-ets.html"}], "objective": "how-is-simple-exponential-smoothing-related-to-arima-0-1-1"}, {"id": "R-167", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does ARIMA need sufficient historical data?", "answer": "To estimate lag relationships and assess forecast reliability; more complex models generally need more observations.", "explanation": "Lag-based models need enough observations to estimate temporal relationships and to evaluate forecasts credibly. Larger orders generally require more fitted relationships and usable history. A single observation-count heuristic cannot guarantee adequacy across all series. Check the model's complexity, data quality, temporal coverage, and held-out performance rather than treating a count alone as sufficient.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}], "objective": "why-does-arima-need-sufficient-historical-data"}, {"id": "R-168", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What does GARCH stand for?", "answer": "Generalized Autoregressive Conditional Heteroscedasticity.", "explanation": "GARCH expands to Generalized Autoregressive Conditional Heteroscedasticity. Conditional heteroscedasticity means that variability can change with available past information. The model represents evolving variance using earlier variances and squared shocks. It addresses volatility rather than directly specifying the expected response level, so interpreting its output requires distinguishing mean behavior from variability.", "links": [], "objective": "what-does-garch-stand-for"}, {"id": "R-169", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "How does GARCH's target differ from ARIMA's?", "answer": "GARCH forecasts variance; ARIMA forecasts response values.", "explanation": "ARIMA describes temporal relationships used to forecast response values or their changes. GARCH describes changing conditional variance, often using errors from a mean model. A series can have a stable expected level but changing uncertainty around it. Mean and variance models can therefore address complementary questions rather than being interchangeable competing outputs.", "links": [], "objective": "how-does-garch-s-target-differ-from-arima-s"}, {"id": "R-170", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "What earlier quantities inform GARCH's variance estimate?", "answer": "Prior variance and squared prediction errors.", "explanation": "Earlier conditional variances represent persistence in volatility, while squared prediction errors represent the magnitudes of recent shocks. Both can influence the next variance estimate. A small new error does not necessarily make predicted variance small if previous variance is high. Squaring the errors removes their signs, because this component concerns fluctuation size.", "links": [], "objective": "what-earlier-quantities-inform-garch-s-variance-estimate"}, {"id": "R-171", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why does basic GARCH have no ARIMA-style differencing order d?", "answer": "It models conditional variance using past variances and squared errors, rather than differencing the response.", "explanation": "Basic GARCH uses past variance and squared errors to describe current conditional variance. It does not contain ARIMA's differencing-order role, which concerns changes in the modeled response series. This does not mean the mean process needs no separate preparation. Read GARCH and ARIMA settings by their respective targets instead of transferring parameter meanings between them.", "links": [{"label": "arch project: mean and volatility model components", "url": "https://arch.readthedocs.io/en/latest/univariate/introduction.html"}], "objective": "why-does-basic-garch-have-no-arima-style-differencing-order-d"}, {"id": "R-172", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "stem": "Why is variance useful for planning?", "answer": "It helps plan for uncertainty, variability, and risk.", "explanation": "An expected response describes a central level, while variance describes uncertainty around it. Two operations with the same predicted average demand can require different buffers if one is much more variable. Variance forecasts can support capacity or risk planning, but the resulting action also depends on costs, constraints, and the consequences of extreme outcomes.", "links": [], "objective": "why-is-variance-useful-for-planning"}, {"id": "C-027", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "smoothing-component-weights", "stem": "How do alpha, beta, and gamma differ in Holt-Winters?", "answer": "Alpha weights the level update; beta weights the trend update; gamma weights the seasonal update.", "explanation": "Alpha directly weights new information in the level update, beta in the trend update, and gamma in the seasonal update. They need not have identical values. A large gamma can rapidly change seasonal ratios even when the level adapts slowly. Interpret each setting in its own recursion because the components interact but have different immediate roles.", "links": [{"label": "Forecasting textbook: seasonal smoothing", "url": "https://otexts.com/fpp3/holt-winters.html"}]}, {"id": "C-028", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "deseasonalized-level-update", "stem": "Why divide by the seasonal factor in a multiplicative level update?", "answer": "To remove that phase's proportional seasonal effect before updating the nonseasonal level.", "explanation": "In a multiplicative model, the observed response includes a proportional seasonal effect. Dividing by its factor estimates what the response would be without that effect. For example, 550 observed with a factor of 1.1 corresponds to a deseasonalized level of 500. Updating the level from 550 directly would mix seasonal amplification into the nonseasonal baseline.", "links": []}, {"id": "C-029", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "differenced-forecast-restoration", "stem": "How is a one-step level forecast recovered from a predicted first difference?", "answer": "Add the predicted difference to the latest observed level.", "explanation": "A first-difference forecast predicts the increment, not the next level. Add it to the last observed level to return to original response units. For example, a latest value of 80 and a predicted change of 5 give a next-level forecast of 85. Higher-order differencing requires additional reconstruction, rather than simply labeling a difference as a level.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}]}, {"id": "C-030", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "garch-error-sign", "stem": "Why do equal positive and negative errors contribute equally to a GARCH squared-error term?", "answer": "Squaring removes the sign; their fluctuation magnitudes are equal.", "explanation": "GARCH's squared-error contribution measures shock magnitude. Errors of +4 and -4 both contribute 16 before multiplication by their coefficient. Thus this component treats equal upward and downward deviations equally. That is a property of the basic squared-error formulation; it does not mean the original signed responses or their operational consequences are identical.", "links": []}, {"id": "C-031", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "variance-response-units", "stem": "What units does a variance forecast use?", "answer": "Squared response units; it is not itself a forecast of the response level.", "explanation": "Variance is expressed in squared response units, whereas a response forecast uses the original units. If demand is measured in items, its variance is measured in items squared. Standard deviation returns to response units by taking a square root. Do not read a numerical variance forecast as the expected level of the future observation.", "links": []}, {"id": "C-032", "module": 7, "topic": "Time series", "kind": "concept", "source": "Concept", "objective": "smoothing-versus-lag-model", "stem": "How do smoothing and ARIMA represent temporal structure differently?", "answer": "Smoothing updates level, trend, and seasonal components; ARIMA uses value/error lags and possible differencing.", "explanation": "Exponential smoothing updates interpretable components such as level, trend, and seasonality. ARIMA represents dependence through value lags, error lags, and possible differencing. Both can be candidates for the same forecasting task, and some specifications overlap. Choose using suitable temporal validation instead of assuming the representation with more parameters is necessarily better.", "links": [{"label": "Forecasting textbook: ARIMA", "url": "https://otexts.com/fpp3/non-seasonal-arima.html"}, {"label": "Forecasting textbook: stationarity and differencing", "url": "https://otexts.com/fpp3/stationarity.html"}]}, {"id": "R-173", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does ordinary linear regression estimate?", "answer": "A numeric response as a function of predictors.", "explanation": "Ordinary linear regression relates a numeric response to predictor columns through an intercept and fitted coefficients. It can summarize associations or estimate responses for new cases. The fitted equation is linear in its coefficients, although the columns may include transformations. Evaluate both fit and assumptions, and do not interpret predictive relationships as automatic evidence of causality.", "links": [], "objective": "what-does-ordinary-linear-regression-estimate"}, {"id": "R-174", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does linear in coefficients mean?", "answer": "The fitted coefficients enter linearly; transformed predictors can still produce curves.", "explanation": "Linear in coefficients means that each fitted coefficient multiplies a specified predictor column and those terms are added. A model beta0+beta1*x+beta2*x^2 is therefore linear regression even though its response curve is quadratic in x. The distinction concerns the fitted parameters, not whether every raw predictor appears as an untransformed straight-line relationship.", "links": [], "objective": "what-does-linear-in-coefficients-mean"}, {"id": "R-175", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What objective does ordinary least squares minimize?", "answer": "Sum of squared residuals.", "explanation": "Ordinary least squares chooses coefficients that minimize sum((y_i-yhat_i)^2). Each residual measures the vertical response difference at the observed predictors. This objective emphasizes larger errors and prevents positive and negative residuals from cancelling. It defines the training fit, rather than directly minimizing every possible operational cost or guaranteeing performance on future cases.", "links": [], "objective": "what-objective-does-ordinary-least-squares-minimize"}, {"id": "R-176", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why square regression residuals?", "answer": "It prevents positive and negative errors from cancelling and penalizes larger errors more.", "explanation": "Adding signed residuals could make a large positive error cancel a large negative error. Squaring avoids that cancellation and gives larger deviations disproportionately more influence. Errors of 1 and 3 contribute 1 and 9 to SSE. This makes least squares sensitive to large residuals, so investigating unusual cases and the chosen objective matters.", "links": [], "objective": "why-square-regression-residuals"}, {"id": "R-177", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How is a regression coefficient interpreted without an interaction?", "answer": "The fitted response change for a one-unit predictor increase, holding other included predictors fixed.", "explanation": "In an additive regression without interactions, a coefficient describes the fitted response difference for a one-unit increase in that predictor with the other included predictors fixed. The units depend on both columns. It is a conditional association within the fitted model, not necessarily a causal effect or the same relationship seen in a one-predictor regression.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "how-is-a-regression-coefficient-interpreted-without-an-interaction"}, {"id": "R-178", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does the intercept represent?", "answer": "The fitted response when the included predictors are zero.", "explanation": "The intercept is the fitted response at the point where all included predictor columns equal zero. Its meaning depends on how predictors are coded and centered. Zero can be a meaningful reference or lie outside the observed range. An awkward intercept interpretation does not by itself make every in-range prediction of the model unusable.", "links": [], "objective": "what-does-the-intercept-represent"}, {"id": "R-179", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does an interaction change an effect?", "answer": "The effect of one predictor can depend on another predictor's value.", "explanation": "An interaction lets one predictor's contribution vary with another predictor. In beta1*x1+beta3*x1*x2, the fitted slope with respect to x1 is beta1+beta3*x2. Therefore beta1 alone describes the slope when x2=0. Interpret the combined terms at the relevant context instead of treating the interaction as just another constant additive effect.", "links": [], "objective": "how-does-an-interaction-change-an-effect"}, {"id": "R-180", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a binary indicator coefficient compare?", "answer": "The fitted difference between the indicated group and its reference group, holding other predictors fixed.", "explanation": "For a zero/one group indicator in an additive model, changing the indicator from zero to one changes the fitted response by its coefficient while other predictors stay fixed. The zero group is the reference. If interactions include the indicator, the group difference can depend on other predictors. Check coding before attaching a group interpretation to the sign.", "links": [], "objective": "what-does-a-binary-indicator-coefficient-compare"}, {"id": "R-181", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why transform predictor columns?", "answer": "To represent relationships the original raw columns do not capture well.", "explanation": "Transformed columns such as x^2, log(x), or x1*x2 let a regression express relationships the raw columns miss. The model can remain linear in its fitted coefficients. Choose transformations for a useful structure and validate them. Their inclusion changes coefficient interpretation, so a slope should be read in relation to the transformed column rather than assumed to act directly on raw x.", "links": [], "objective": "why-transform-predictor-columns"}, {"id": "R-182", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why does transforming the response require interpretation care?", "answer": "The output and coefficients now use a different response scale.", "explanation": "Transforming the response changes what the model predicts and the scale on which residuals and slopes are defined. A model for log(y) does not directly predict y in original units. Returning to those units requires an appropriate inverse transformation and interpretation. Do not compare raw coefficients or errors across response scales as though their meanings were unchanged.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "why-does-transforming-the-response-require-interpretation-care"}, {"id": "R-183", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is a regression residual?", "answer": "Observed response minus fitted response.", "explanation": "A residual is y-yhat for a case, measured in the response direction at its observed predictors. A positive residual means the model underpredicted that response; a negative one means it overpredicted. It is not generally the shortest geometric distance to the fitted line. Residual patterns can reveal structure the fitted model missed.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}], "objective": "what-is-a-regression-residual"}, {"id": "R-184", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a funnel-shaped residual plot suggest?", "answer": "Changing error spread across fitted values.", "explanation": "A funnel shape means residual spread changes across fitted values, suggesting nonconstant error variance. The mean relationship can still look reasonable while uncertainty varies with the level. Investigate scale, transformations, and the assumptions used for inference. The pattern does not mean every predictor must be transformed or that all large residuals are invalid observations.", "links": [], "objective": "what-does-a-funnel-shaped-residual-plot-suggest"}, {"id": "R-185", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What do long residual runs over time suggest?", "answer": "Possible temporal dependence or missing time structure.", "explanation": "Long sequences of positive or negative residuals suggest that errors may not be behaving independently over time, or that the fitted model omitted temporal structure. Random-looking scatter around zero is different from sustained runs. Inspect order and context rather than evaluating only overall SSE, because temporal dependence can matter for forecasts and uncertainty estimates.", "links": [], "objective": "what-do-long-residual-runs-over-time-suggest"}, {"id": "R-186", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does residual curvature suggest?", "answer": "A missing nonlinear relationship or unsuitable functional form.", "explanation": "A systematic curve in residuals indicates that errors depend on where a case lies in the fitted relationship. The model may be missing curvature, an interaction, or another meaningful predictor. Residuals that average near zero overall can still have this structure. Check the functional form rather than assuming a small average signed error establishes a good model.", "links": [], "objective": "what-does-residual-curvature-suggest"}, {"id": "R-187", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can strongly correlated predictors complicate separate coefficient interpretation?", "answer": "Their overlapping information can make separate coefficient interpretations difficult.", "explanation": "Strongly correlated predictors contain overlapping information, making it difficult to separate their individual contributions. Coefficient estimates can become sensitive to small data changes even when combined predictions remain useful. Interpret slopes conditionally and inspect uncertainty. A large standard error does not necessarily mean the underlying attribute carries no predictive information in combination with the others.", "links": [], "objective": "why-can-strongly-correlated-predictors-complicate-separate-coefficient-interpretation"}, {"id": "R-188", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can marginal and multiple-regression coefficient signs differ?", "answer": "Conditioning on other predictors can change the apparent relationship.", "explanation": "A marginal relationship considers one predictor alone, while a multiple-regression coefficient conditions on the other included predictors. Shared associations can therefore change its magnitude or even its sign. This is not automatically a computational mistake. Ask what is being held fixed and which variables changed between specifications before interpreting the apparent reversal.", "links": [], "objective": "why-can-marginal-and-multiple-regression-coefficient-signs-differ"}, {"id": "R-189", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is likelihood?", "answer": "How compatible the observed data are with specified model parameters and assumptions.", "explanation": "Likelihood evaluates the observed data as a function of candidate parameter values under the model assumptions. For continuous data it uses densities rather than the probability of one exact observation. A larger likelihood indicates better compatibility within that formulation. It is not automatically a probability distribution over parameter values or proof that the model is true.", "links": [], "objective": "what-is-likelihood"}, {"id": "R-190", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "When does Gaussian maximum likelihood match least squares?", "answer": "Under independent, identically distributed normal errors.", "explanation": "For regression with independent normal errors of common variance, the likelihood penalizes squared residuals. Maximizing it over the regression coefficients therefore yields the same coefficient fit as minimizing SSE. This connection relies on the stated error formulation. It does not imply that every likelihood-based model is ordinary least squares or that normality is required to compute OLS coefficients.", "links": [], "objective": "when-does-gaussian-maximum-likelihood-match-least-squares"}, {"id": "R-191", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does AIC combine likelihood and model size?", "answer": "AIC = -2*log-likelihood + 2*K; lower comparable scores are preferred.", "explanation": "AIC balances fit and complexity using -2*log-likelihood+2*K, where K counts fitted parameters under a consistent convention. A better likelihood reduces the score, while more parameters increase it. Prefer a lower score among comparable models. The criterion discourages unsupported flexibility but does not establish causality or replace evaluation of actual predictive performance.", "links": [{"label": "ISLR model-selection resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-aic-combine-likelihood-and-model-size"}, {"id": "R-192", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is AICc?", "answer": "AIC with a finite-sample correction.", "explanation": "AICc adds a finite-sample correction to AIC, making complexity more costly when the sample is small relative to the number of fitted parameters. The correction becomes less influential as sample size grows for a fixed specification. Compare it under consistent likelihood and parameter conventions rather than treating its numerical value as a universal measure of model truth.", "links": [], "objective": "what-is-aicc"}, {"id": "R-193", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "How does BIC combine likelihood and model size?", "answer": "BIC = -2*log-likelihood + K*log(n); lower comparable scores are preferred.", "explanation": "BIC uses -2*log-likelihood+K*log(n), balancing the same likelihood fit against a sample-size-dependent parameter penalty. Lower scores are preferred on comparable data. When log(n)>2, each extra parameter receives a larger penalty than in AIC. This can favor simpler specifications, but the selected model still needs interpretation and appropriate predictive evaluation.", "links": [{"label": "ISLR model-selection resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-bic-combine-likelihood-and-model-size"}, {"id": "R-194", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is relative AIC support for a model Delta above the best?", "answer": "exp(-Delta/2), as a relative comparison rather than proof of truth.", "explanation": "Let Delta be a candidate's AIC minus the lowest AIC among the compared models. Its relative support is exp(-Delta/2), so Delta=4 gives about 0.135 relative to the best candidate. The calculation expresses a comparison within the candidate set. It is not a probability that the model is true or a guaranteed forecast-success rate.", "links": [], "objective": "what-is-relative-aic-support-for-a-model-delta-above-the-best"}, {"id": "R-195", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What must be consistent when comparing information criteria?", "answer": "Response, observations, likelihood convention, and parameter counting.", "explanation": "Information-criterion differences have meaning only when the likelihoods refer to comparable responses and observations and follow consistent conventions. Parameter counts must also be consistent. Changing the sample or response scale can change the criterion for reasons unrelated to modeling quality. Do not declare a winner simply by comparing unrelated raw software scores.", "links": [], "objective": "what-must-be-consistent-when-comparing-information-criteria"}, {"id": "R-196", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is a coefficient standard error?", "answer": "Estimated sampling uncertainty in a fitted coefficient.", "explanation": "A coefficient standard error estimates how uncertain the fitted coefficient is due to sampling variation under the model assumptions. It concerns the coefficient estimate, rather than the spread of raw predictor values or individual prediction errors. Compare it with the coefficient's magnitude when interpreting evidence, and check assumptions that justify the uncertainty calculation.", "links": [], "objective": "what-is-a-coefficient-standard-error"}, {"id": "R-197", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is the coefficient t-statistic for a specified null value?", "answer": "(Estimated coefficient - null value)/standard error; for a zero null, coefficient/standard error.", "explanation": "A coefficient t-statistic measures the estimate's distance from a specified null value in standard-error units: (estimate-null)/SE. For a zero null, an estimate of 6 with SE=2 gives t=3. Its sign follows the direction of the difference. The corresponding test interpretation depends on the reference distribution and model assumptions.", "links": [], "objective": "what-is-the-coefficient-t-statistic-for-a-specified-null-value"}, {"id": "R-198", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a p-value mean?", "answer": "Under the null and assumptions, the probability of a result at least as extreme as observed.", "explanation": "A p-value is computed assuming the null hypothesis and the test assumptions. It measures the probability of a test result at least as extreme as the observed result under that setup. A value of 0.02 is not a 2% probability that the coefficient is zero. It also does not describe the effect's size or operational importance.", "links": [{"label": "StatQuest p-value video", "url": "https://youtu.be/vemZtEM63GY"}, {"label": "ISLR regression-inference resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-a-p-value-mean"}, {"id": "R-199", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why is a significant coefficient not necessarily important?", "answer": "Statistical evidence does not establish a large or valuable effect.", "explanation": "Statistical significance describes evidence relative to a null and its assumptions, while practical importance concerns magnitude and consequences. With many observations, a tiny effect can be estimated precisely and receive a small p-value. Examine units, effect size, uncertainty, and decision relevance rather than treating a significance cutoff as an automatic measure of usefulness.", "links": [], "objective": "why-is-a-significant-coefficient-not-necessarily-important"}, {"id": "R-200", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What does a confidence interval including zero imply for a matching two-sided test?", "answer": "No rejection of zero at the matching level, not proof of no relationship.", "explanation": "For matching assumptions and a matching two-sided level, a coefficient interval containing zero corresponds to not rejecting a zero coefficient. This means the evidence is insufficient for that rejection, not that zero has been proved. The interval may also contain effects large enough to matter operationally, so inspect its range as well as the test decision.", "links": [], "objective": "what-does-a-confidence-interval-including-zero-imply-for-a-matching-two-sided-test"}, {"id": "R-201", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is ordinary R-squared?", "answer": "1-SSE/SST: fitted response variation explained relative to the mean baseline.", "explanation": "Ordinary R-squared compares the model's SSE with the variation around the sample response mean: 1-SSE/SST. A value of 0.6 means the fitted model accounts for 60% of that sample variation under this definition. It is not 60% classification accuracy, a causal percentage, or an assurance that predictions for new cases will be equally good.", "links": [], "objective": "what-is-ordinary-r-squared"}, {"id": "R-202", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can adding predictors increase R-squared without improving prediction?", "answer": "Additional flexibility can fit training noise.", "explanation": "In nested ordinary least-squares fits on the same training data, the larger model can retain the old solution by giving added predictors zero coefficients. Its training SSE therefore cannot increase, so ordinary training R-squared cannot decrease. Extra predictors may still fit sample noise. Check held-out performance rather than equating a higher training R-squared with better prediction.", "links": [], "objective": "why-can-adding-predictors-increase-r-squared-without-improving-prediction"}, {"id": "R-203", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "What is adjusted R-squared?", "answer": "R-squared adjusted for model size; it can fall when predictors are added.", "explanation": "Adjusted R-squared accounts for the number of included predictors as well as training fit. Adding a predictor must improve fit enough to compensate for that adjustment; otherwise the adjusted score can fall. It is a model-size-aware summary, not a substitute for held-out evaluation. Interpret it separately from ordinary R-squared and classification accuracy.", "links": [], "objective": "what-is-adjusted-r-squared"}, {"id": "R-204", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why can held-out R-squared be negative?", "answer": "Its squared error can exceed the evaluation mean-response baseline's error.", "explanation": "Using 1-SSE/SST on held-out cases can yield a negative value when the predictions have more squared error than the specified mean-response baseline. For example, SSE twice SST gives R-squared=-1. This is possible because the model was not fitted to minimize that evaluation error. State the baseline convention when comparing reported held-out scores.", "links": [], "objective": "why-can-held-out-r-squared-be-negative"}, {"id": "R-205", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "stem": "Why do predictive associations and change signals not establish causality?", "answer": "They can reflect shared causes, reverse relationships, or selection; they do not identify intervention effects.", "explanation": "Prediction and association identify relationships in observed information, rather than the effects of deliberate interventions. Shared causes, reverse relationships, and selection can generate strong patterns without the assumed causal mechanism. A detected change also does not establish why it occurred. Use the model's evidence for its actual claim instead of converting predictive success into a causal conclusion.", "links": [{"label": "StatQuest p-value video", "url": "https://youtu.be/vemZtEM63GY"}, {"label": "ISLR regression-inference resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-do-predictive-associations-and-change-signals-not-establish-causality"}, {"id": "C-033", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "objective": "intercept-range-caution", "stem": "Why can a regression intercept lack a useful operational interpretation?", "answer": "The zero-predictor condition may be outside the observed or meaningful range.", "explanation": "A regression can predict zero-predictor cases mathematically even when those cases are outside the meaningful range. An intercept for building energy use at zero floor area may therefore lack a useful operational interpretation. The equation still needs an intercept. Centering can change the reference point, but assess prediction usefulness within the data range rather than from the intercept alone.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-034", "module": 8, "topic": "Regression and inference", "kind": "concept", "source": "Concept", "objective": "error-scale-conversion", "stem": "How do residuals and SSE change under a common response-unit factor a?", "answer": "Residuals scale by a; SSE scales by a squared.", "explanation": "If both observed and fitted responses are multiplied by a common factor a, each residual is multiplied by a. Squaring makes each SSE contribution multiply by a squared. Converting units therefore changes raw error magnitudes without necessarily changing model quality. Compare errors on the same response scale before interpreting one numeric SSE as better than another.", "links": [{"label": "ISLR linear-regression resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: multiple regression", "url": "https://statquest.org/video_index.html"}]}, {"id": "R-206", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What family of response transformations does Box-Cox provide?", "answer": "Power transformations of positive responses, with logarithms as the zero-power case.", "explanation": "Box-Cox applies a family of power transformations to positive responses. For a nonzero power lambda, it uses (y^lambda-1)/lambda; the zero-power case uses log(y). Thus it is not always a logarithm. The selected power changes the response scale, requiring appropriate interpretation and conversion when reporting predictions in original units.", "links": [], "objective": "what-family-of-response-transformations-does-box-cox-provide"}, {"id": "R-208", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What can Box-Cox try to improve?", "answer": "Response shape and model behavior, including error-spread patterns; improvement is not guaranteed.", "explanation": "A response transformation can make a relationship easier to model or reduce patterns such as increasing error spread. Box-Cox offers a family of candidates for that purpose. Improvement is not guaranteed, so examine fitted residuals and evaluation results afterward. A more symmetric response histogram alone does not establish that every modeling assumption now holds.", "links": [], "objective": "what-can-box-cox-try-to-improve"}, {"id": "R-209", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Does ordinary regression require a normal raw-response histogram?", "answer": "No. The relevant normal-error assumptions concern errors, not just the raw histogram.", "explanation": "Normal-error assumptions concern response deviations conditional on predictors, rather than demanding a normal histogram of all raw responses. Different predictor groups can produce a skewed or mixed raw-response distribution even with reasonable conditional errors. Examine residual behavior and the specified relationship instead of accepting or rejecting regression solely from the unconditioned response histogram.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "does-ordinary-regression-require-a-normal-raw-response-histogram"}, {"id": "R-210", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is heteroscedasticity?", "answer": "Nonconstant error variance.", "explanation": "Heteroscedasticity means error variance changes with predictor values, fitted levels, or other conditions. For example, residuals may be small at low expected demand and much more spread out at high demand. This differs from a curved mean error pattern. It can affect uncertainty statements, so inspect spread separately from the average fitted relationship.", "links": [], "objective": "what-is-heteroscedasticity"}, {"id": "R-211", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is detrending?", "answer": "Remove an estimated or known systematic temporal baseline.", "explanation": "Detrending subtracts a systematic temporal baseline, such as an estimated rising line, to analyze the remaining variation. It separates the modeled trend from fluctuations around it. Fit any learned trend using permitted training data. If forecasts are needed on the original scale, the corresponding future trend must later be restored.", "links": [], "objective": "what-is-detrending"}, {"id": "R-212", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How does detrending differ from differencing?", "answer": "Detrending removes a baseline function; differencing subtracts neighboring observations.", "explanation": "Detrending removes a chosen baseline function from each observation. Differencing instead subtracts neighboring observations, changing levels into changes. They can both address temporal structure but produce different modeled quantities. After subtractive detrending, add the baseline back; after first differencing, reconstruct levels by adding predicted increments to the latest known level.", "links": [], "objective": "how-does-detrending-differ-from-differencing"}, {"id": "R-213", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How do you recover original-scale predictions after subtractive detrending?", "answer": "Add the fitted trend back to the predicted remaining component.", "explanation": "A detrended model predicts the component remaining after the original trend was subtracted. Recover an original-scale forecast by adding the trend evaluated at the forecast time. For example, a predicted remainder of 5 and projected baseline of 100 give 105. Forgetting restoration confuses a deviation from trend with the response itself.", "links": [], "objective": "how-do-you-recover-original-scale-predictions-after-subtractive-detrending"}, {"id": "R-214", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What does ordinary PCA do, and what information defines its directions?", "answer": "It creates orthogonal directions ranked by prepared predictor variance, without using response labels.", "explanation": "Ordinary PCA constructs new orthogonal coordinate directions using the prepared predictors. It orders them by the predictor variance they explain, without using response labels. The first direction captures the most variation under that preparation. High predictor variance can be useful for compression, but does not guarantee that the retained directions contain the strongest predictive information about y.", "links": [], "objective": "what-does-ordinary-pca-do-and-what-information-defines-its-directions"}, {"id": "R-215", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why center data before ordinary PCA?", "answer": "To measure variation around feature means; scaling also matters when units differ.", "explanation": "Centering makes PCA describe variation around feature means rather than position relative to an arbitrary origin. Scaling also determines how different units influence the covariance structure. Large-unit features can dominate unscaled PCA. Estimate preparation from training cases and apply it consistently to new cases so the fitted component directions retain their meaning.", "links": [], "objective": "why-center-data-before-ordinary-pca"}, {"id": "R-216", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What matrix gives ordinary PCA loading directions?", "answer": "The prepared predictors' covariance/correlation matrix or equivalent centered cross-product matrix.", "explanation": "PCA directions can be obtained from the covariance matrix of centered predictors, or the correlation matrix when variables are standardized. An equivalent centered cross-product formulation gives the same directions under compatible conventions. These matrices describe relationships within X, rather than X's association with a response. Preparation therefore shapes the extracted components.", "links": [], "objective": "what-matrix-gives-ordinary-pca-loading-directions"}, {"id": "R-217", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is a principal component loading?", "answer": "An original feature's weight in a component direction.", "explanation": "Loadings are the weights defining a principal-component direction in terms of the prepared original features. They describe how the coordinate axis combines those features. Their magnitudes and signs aid interpretation, but the overall direction can be sign-reversed without changing the substantive axis. Distinguish loadings from an individual observation's projected score.", "links": [], "objective": "what-is-a-principal-component-loading"}, {"id": "R-218", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is a principal component score?", "answer": "An observation's value after projection onto a component direction.", "explanation": "A principal-component score is an observation's coordinate along a fitted loading direction. Compute it by projecting that observation's prepared feature vector onto the direction. Different observations have different scores but share the same fitted loadings. Subsequent regression can use scores as predictors, provided new cases are projected with the training preparation and directions.", "links": [], "objective": "what-is-a-principal-component-score"}, {"id": "R-219", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is an eigenvector/eigenvalue relationship?", "answer": "A*v=lambda*v: the direction is preserved while its magnitude is scaled.", "explanation": "An eigenvector v of matrix A satisfies A*v=lambda*v, meaning the matrix changes its scale without changing its direction. In PCA, eigenvectors provide loading directions and eigenvalues quantify variation along them. The relationship is about the predictor geometry. It does not itself provide response-regression coefficients or prove which direction best predicts an outcome.", "links": [], "objective": "what-is-an-eigenvector-eigenvalue-relationship"}, {"id": "R-220", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What fraction of X variance does a component explain?", "answer": "Its eigenvalue divided by the total eigenvalues.", "explanation": "A component's explained predictor-variance fraction is its eigenvalue divided by the sum of all eigenvalues. If its eigenvalue is 6 and the total is 10, it explains 60% of the prepared X variance. That percentage does not describe response variance explained by regression or a classification success rate.", "links": [], "objective": "what-fraction-of-x-variance-does-a-component-explain"}, {"id": "R-221", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why can retaining all PCA directions preserve information?", "answer": "A complete coordinate change retains all dimensions.", "explanation": "Keeping every PCA direction preserves the centered predictor information through a complete change of coordinates. Compression occurs when only some directions are retained. Re-expressing the same information can reduce correlated-coordinate difficulties but does not automatically add predictive information. Any claim of reduced dimensionality should specify which components were discarded rather than just noting that PCA was performed.", "links": [], "objective": "why-can-retaining-all-pca-directions-preserve-information"}, {"id": "R-222", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why does ordinary PCA not guarantee better response prediction?", "answer": "PCA uses predictor variance, not the response, to choose directions.", "explanation": "PCA selects directions for high predictor variance without consulting the response. A low-variance direction can still be strongly related to the outcome, so truncating it can reduce predictive quality. Evaluate the downstream model on held-out cases. A statement such as retaining 90% of X variance is not a guarantee of retaining 90% of predictive accuracy.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-does-ordinary-pca-not-guarantee-better-response-prediction"}, {"id": "R-224", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What is feature extraction versus feature selection?", "answer": "Extraction creates combinations; selection keeps original variables.", "explanation": "Feature selection chooses a subset of existing variables, retaining their original identities. Feature extraction creates new representations, often combinations of the originals. PCA is extraction because a score can combine several predictor columns. Both affect the information supplied to a later model, but differ in interpretation and in how new observations must be transformed.", "links": [], "objective": "what-is-feature-extraction-versus-feature-selection"}, {"id": "R-225", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "How are component-regression coefficients mapped back?", "answer": "Combine the fitted component slopes with the corresponding loadings.", "explanation": "A regression on component scores assigns slopes to those new coordinates. Substitute each score's loading-weighted feature expression into the fitted regression and combine terms to obtain slopes in the prepared original-feature coordinates. If features were standardized, those are not yet raw-unit slopes. Account for scaling and centering before interpreting the original-unit equation.", "links": [], "objective": "how-are-component-regression-coefficients-mapped-back"}, {"id": "R-226", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What raw-unit correction follows regression on standardized PCA scores?", "answer": "Undo training scaling and centering before interpreting original-unit slopes and the intercept.", "explanation": "Standardized features use (x_j-mean_j)/SD_j. After combining component slopes with loadings, divide each prepared-coordinate slope by its training SD to recover its raw-unit slope. Adjust the intercept for the subtracted means. The same fitted predictions can be represented in either coordinate system, but coefficients have different units until these corrections are applied.", "links": [], "objective": "what-raw-unit-correction-follows-regression-on-standardized-pca-scores"}, {"id": "R-227", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why do strongly correlated standardized predictors often yield one dominant PC?", "answer": "Shared movement concentrates predictor variance in one direction.", "explanation": "Strongly positively correlated standardized features often vary together along a diagonal direction. PCA can concentrate much of their combined variance in that direction and leave less along the orthogonal difference direction. This describes shared predictor movement, not automatically response relevance. Inspect retained variance and downstream validation before discarding the smaller component.", "links": [], "objective": "why-do-strongly-correlated-standardized-predictors-often-yield-one-dominant-pc", "diagram": "pca"}, {"id": "R-228", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "What should guide choosing how many PCA components to retain for prediction?", "answer": "Predictor-variance retention and downstream validation, not a guaranteed response-accuracy percentage.", "explanation": "For compression, explained X variance is a useful guide. For prediction, also evaluate the model trained on the retained scores, because variance ranking does not use y. The useful number of components can differ between these goals. Fit PCA within training boundaries during selection, and do not interpret a variance-retention percentage as a response-accuracy promise.", "links": [], "objective": "what-should-guide-choosing-how-many-pca-components-to-retain-for-prediction"}, {"id": "R-229", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "stem": "Why must test PCA use the training loadings?", "answer": "New cases must use the same coordinate system as the fitted model.", "explanation": "A model fitted to training component scores expects inputs in those particular directions. Test cases must use the training means, scales, and loadings. Refitting PCA on the test batch can rotate or reorder the coordinates, giving its scores different meanings. That changes the model's input interpretation and also lets evaluation information influence the transformation.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-must-test-pca-use-the-training-loadings"}, {"id": "C-035", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "pca-axis-sign", "stem": "Does reversing a PCA axis imply a different substantive component?", "answer": "No. Reversing its loadings and scores describes the same axis.", "explanation": "An axis has the same geometric meaning when its direction is reversed. Reversing a PCA loading vector reverses all associated scores but preserves explained variance. In a regression, also reverse the corresponding slope to preserve the product of score and slope. Sign differences between PCA outputs therefore do not necessarily indicate different substantive components.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-036", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "equal-eigenvalue-interpretation", "stem": "What do equal PCA eigenvalues imply about variance importance?", "answer": "Those directions have equal predictor variance; the ranking alone does not favor one.", "explanation": "Equal eigenvalues mean equal predictor variance along the associated orthogonal directions. The variance ranking alone cannot favor one of them. It also does not establish that the original features are duplicates, equally causal, or equally predictive of y. Interpret the component subspace and downstream task rather than inventing a unique importance order from tied variances.", "links": [{"label": "StatQuest PCA video", "url": "https://youtu.be/FgakZw6K1QQ"}, {"label": "ISLR unsupervised-learning resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-037", "module": 9, "topic": "PCA and transformations", "kind": "concept", "source": "Concept", "objective": "predictor-response-transform-contrast", "stem": "How does a predictor transformation differ from a response transformation?", "answer": "A predictor transformation changes inputs; a response transformation changes the output scale.", "explanation": "Transforming a predictor changes the inputs used to estimate a response, while transforming the response changes the output scale being modeled. A regression using x^2 can still predict original-unit y. A regression predicting log(y) requires an inverse transformation for original-unit output. Coefficient interpretation follows the transformed quantity, so identify which side of the model changed.", "links": [{"label": "NIST Box-Cox explanation", "url": "https://www.itl.nist.gov/div898/handbook/pmc/section5/pmc52.htm"}, {"label": "ISLR regression resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "R-230", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does CART stand for?", "answer": "Classification and Regression Trees.", "explanation": "CART stands for Classification and Regression Trees. It recursively partitions predictor space and assigns a prediction within each terminal region. Classification uses known categorical responses, while regression uses numeric responses. The resulting path can be read as sequential rules. Fitting splits and controlling tree size are important because overly detailed partitions can memorize training noise.", "links": [], "objective": "what-does-cart-stand-for"}, {"id": "R-231", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does an ordinary regression leaf predict?", "answer": "The mean of the training responses in that leaf.", "explanation": "An ordinary squared-error regression tree predicts the mean of the training responses assigned to a leaf. Cases reaching that leaf receive the same numeric prediction. For example, responses of 2, 4, and 9 yield a prediction of 5. A model tree fitting a local regression inside each leaf is a different specification.", "links": [], "objective": "what-does-an-ordinary-regression-leaf-predict"}, {"id": "R-232", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does a classification leaf predict?", "answer": "The most frequent class in that leaf.", "explanation": "An ordinary classification leaf predicts its most frequent training class under the stated rule. Class fractions can also supply probability estimates. If seven of ten leaf cases are class A, its majority prediction is A. The training proportion is a fitted estimate, not a certainty that every new case reaching the leaf has that class.", "links": [], "objective": "what-does-a-classification-leaf-predict"}, {"id": "R-233", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a model tree compared with ordinary CART?", "answer": "It fits a richer local model in each leaf instead of only a constant response.", "explanation": "Ordinary regression CART uses one constant prediction, the leaf response mean, in each terminal region. A model tree instead fits a richer local relationship, such as a regression using predictors within that leaf. More flexibility can improve fit but needs enough supporting cases and validation. Do not assume every regression tree leaf contains a fitted line.", "links": [], "objective": "what-is-a-model-tree-compared-with-ordinary-cart"}, {"id": "R-234", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What are root,internal node,and leaf?", "answer": "Root: start. Internal node: split. Leaf: terminal prediction.", "explanation": "The root is the first decision point for every case. Internal nodes apply further split rules, and leaves provide final predictions once no further split is followed. A new case traverses one path from root to leaf. The order of tests matters because later rules apply only to the region selected by earlier decisions.", "links": [], "objective": "what-are-root-internal-node-and-leaf"}, {"id": "R-235", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is recursive binary splitting?", "answer": "Repeatedly split the current region using a feature and threshold.", "explanation": "Recursive binary splitting divides the current predictor region into two children, then applies further splits within selected children. Each later rule is conditional on the previous path. A tree can create a complex partition even when each split uses one feature threshold. Follow the entire path for a new case rather than treating all displayed tests as simultaneous global rules.", "links": [], "objective": "what-is-recursive-binary-splitting", "diagram": "tree"}, {"id": "R-236", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why compare child SSE or weighted variances in regression splits?", "answer": "Larger children contain more cases and contribute more to overall fit.", "explanation": "A regression split is evaluated through its combined child error, usually the sum of child SSE values. Large children contain more cases, so equal weighting of child variances can distort the comparison. Account for sizes when translating variances into overall error. A very pure tiny child does not necessarily make the full split better.", "links": [], "objective": "why-compare-child-sse-or-weighted-variances-in-regression-splits"}, {"id": "R-237", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Which controls limit tree growth and unsupported leaves?", "answer": "Minimum leaf size, required split improvement, depth limits, and pruning.", "explanation": "Minimum leaf size, depth limits, required improvement, and pruning restrict how finely a tree partitions training cases. They can prevent unsupported leaves and reduce overfitting. Each control acts differently: a minimum leaf size constrains child support, while pruning removes branches after growth. Select suitable settings through evaluation instead of assuming maximum tree detail is best.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "which-controls-limit-tree-growth-and-unsupported-leaves"}, {"id": "R-238", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does pruning do?", "answer": "Remove branches that do not improve evaluated performance.", "explanation": "Pruning removes branches whose additional complexity is not supported by the evaluation criterion. It simplifies a grown tree, often using validation evidence. Pruning can worsen training fit while improving generalization by removing sample-specific splits. Data used to choose pruning have a selection role and should not simultaneously be treated as an untouched final test set.", "links": [], "objective": "what-does-pruning-do"}, {"id": "R-239", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should a percentage-based minimum leaf-size guideline be interpreted?", "answer": "As a heuristic for limiting tiny leaves, not a universal optimal setting.", "explanation": "A minimum leaf-size percentage is a practical constraint on how much data supports each final prediction. It is a heuristic rather than an optimal constant for every dataset. The suitable value depends on available observations, response variability, and validation performance. Apply the requirement to each proposed child, not only to the parent's size or the children on average.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "how-should-a-percentage-based-minimum-leaf-size-guideline-be-interpreted"}, {"id": "R-240", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should the factor-model observations-per-factor guideline be interpreted?", "answer": "Roughly ten observations per selected factor is a heuristic, not guaranteed adequacy.", "explanation": "Observations-per-factor rules summarize the concern that a model needs enough information for the relationships it estimates. A rough ten-per-factor guideline is not a theorem or guarantee. Correlated predictors, noisy data, and population coverage can make a nominal count inadequate. Consider uncertainty and validation rather than deciding model adequacy from the ratio alone.", "links": [], "objective": "how-should-the-factor-model-observations-per-factor-guideline-be-interpreted"}, {"id": "R-241", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does raising a tree's required split improvement usually affect growth?", "answer": "A larger required improvement usually permits fewer marginal splits.", "explanation": "Requiring a larger improvement makes a split harder to accept. This usually removes marginal divisions and yields a simpler tree under comparable fitting conditions. It differs from changing the maximum depth or leaf-size requirement, even though all can limit growth. A reduced training fit may still produce better held-out performance if the rejected splits mostly captured noise.", "links": [], "objective": "how-does-raising-a-tree-s-required-split-improvement-usually-affect-growth"}, {"id": "R-243", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does random predictor selection help a random forest?", "answer": "It diversifies trees by limiting the candidate predictors considered at each split.", "explanation": "Random forests limit the candidate predictors considered at each split, encouraging different trees to use different relationships. This can reduce similarity among tree predictions and errors. It is distinct from resampling observations. Diversification supports useful averaging or voting, but the choices still need to fit the data and task rather than automatically ensuring improvement.", "links": [{"label": "StatQuest random-forest video", "url": "https://youtu.be/J4Wdy0Wc_xQ"}, {"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "how-does-random-predictor-selection-help-a-random-forest"}, {"id": "R-244", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How does a forest aggregate predictions?", "answer": "Average numeric predictions; combine votes for class predictions.", "explanation": "For a numeric response, a forest ordinarily averages the trees' predictions. For a class response, it combines their class votes or probabilities under the chosen convention. Aggregation pools multiple fitted rules, rather than selecting a single leaf from the entire forest. It can stabilize results when tree errors differ, but shared systematic mistakes can remain.", "links": [], "objective": "how-does-a-forest-aggregate-predictions"}, {"id": "R-245", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "When can combining trees reduce overreaction to training noise?", "answer": "When their mistakes differ enough to partly offset; shared mistakes can persist.", "explanation": "Combining trees is most useful when their errors are not perfectly aligned. Some positive and negative errors can offset in an average, and varied class votes can reduce reliance on an unstable single partition. If every tree misses the same relationship or uses leaked information, adding trees does not repair that common problem.", "links": [], "objective": "when-can-combining-trees-reduce-overreaction-to-training-noise"}, {"id": "R-249", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How should correct training classifications be combined across differently sized leaves?", "answer": "Add correct cases and total cases across leaves; do not average leaf percentages without their sizes.", "explanation": "Overall accuracy weights leaves by their numbers of cases. Add the correct counts across leaves, then divide by the total number of cases. For example, leaves with 9/10 and 50/100 correct give 59/110 overall, not the unweighted average of 90% and 50%. Evaluate on the intended cases rather than confusing training purity with future accuracy.", "links": [], "objective": "how-should-correct-training-classifications-be-combined-across-differently-sized-leaves"}, {"id": "R-250", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is forest variable importance not a causal coefficient?", "answer": "Predictive contribution does not establish a signed, constant, causal effect.", "explanation": "Forest importance summarizes predictive usefulness under a particular fitted procedure and importance definition. It is not a constant signed slope and does not identify what would happen if the feature were deliberately changed. Correlated features can share predictive information. Use importance to understand model reliance, while avoiding unsupported causal interpretations of its ranking.", "links": [{"label": "StatQuest random-forest video", "url": "https://youtu.be/J4Wdy0Wc_xQ"}, {"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "why-is-forest-variable-importance-not-a-causal-coefficient"}, {"id": "R-251", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is logistic regression's predicted probability?", "answer": "p=1/(1+exp(-eta)), where eta is the fitted linear predictor.", "explanation": "Logistic regression converts a linear predictor eta into p=1/(1+exp(-eta)), keeping fitted probabilities between zero and one. At eta=0, p=0.5; increasing eta increases p. The probability estimate is separate from the class decision. A threshold or cost-based rule is still required to turn p into an action.", "links": [], "objective": "what-is-logistic-regression-s-predicted-probability"}, {"id": "R-252", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What response data fit basic binary logistic regression?", "answer": "Known binary outcomes, coded 0/1, and suitable predictors.", "explanation": "Basic binary logistic regression uses known responses with two categories, commonly coded zero and one, together with predictor columns. The fitted probability refers specifically to the category coded one. Changing that coding changes the interpretation. Inputs can include suitably represented numeric or categorical information, and their availability must match the intended prediction setting.", "links": [], "objective": "what-response-data-fit-basic-binary-logistic-regression"}, {"id": "R-253", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why can ordinary linear regression be unsuitable for predicting a binary-event probability?", "answer": "Its numeric predictions can fall outside zero to one.", "explanation": "Ordinary linear regression does not constrain numeric predictions to the probability interval. A fitted value below zero or above one cannot be read directly as an event probability. Logistic regression instead uses a bounded probability transformation. This distinction concerns modeling probabilities; it does not imply that every numeric target should use logistic regression.", "links": [], "objective": "why-can-ordinary-linear-regression-be-unsuitable-for-predicting-a-binary-event-probability"}, {"id": "R-255", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How is basic logistic regression normally fitted?", "answer": "Iterative likelihood-based fitting, not ordinary closed-form least squares.", "explanation": "Logistic regression usually fits coefficients by maximizing the binary-response likelihood through an iterative numerical procedure. Its bounded probability relationship does not give the ordinary closed-form least-squares solution. You need the high-level fitting distinction, not a derivation of the algorithm. As with other supervised models, evaluate the fitted procedure on representative held-out cases.", "links": [], "objective": "how-is-basic-logistic-regression-normally-fitted"}, {"id": "R-256", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does a logistic threshold do?", "answer": "It turns a probability estimate into a class or action.", "explanation": "A logistic model estimates an event probability, while the decision threshold specifies when that probability counts as a positive class or action. The same probabilities can support different thresholds for different consequences. A threshold change need not refit the probability model. Evaluate the resulting tradeoff in false positives, false negatives, and operational cost.", "links": [], "objective": "what-does-a-logistic-threshold-do"}, {"id": "R-257", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is a threshold of .5 not automatically best?", "answer": "Different errors and actions can have different consequences.", "explanation": "A 0.5 threshold treats the estimated positive probability as exceeding the negative probability, but it does not automatically represent decision value. If missing a positive case is much more expensive than a false alarm, a lower threshold can be useful. The appropriate choice also relies on probability quality and the stated costs and population.", "links": [], "objective": "why-is-a-threshold-of-5-not-automatically-best"}, {"id": "R-258", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What happens when a fixed positive-score threshold increases?", "answer": "Fewer or the same positive predictions; misses can rise and false alarms can fall.", "explanation": "For fixed scores with positive predictions assigned above a threshold, raising that threshold can only shrink or preserve the positive set. True-positive detections and false-positive alarms can therefore decrease or remain unchanged. The effect on accuracy or total cost is not predetermined. Equality handling and gaps between observed scores can produce intervals with no decision changes.", "links": [], "objective": "what-happens-when-a-fixed-positive-score-threshold-increases"}, {"id": "R-259", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Why is pseudo-R-squared different from ordinary R-squared?", "answer": "It is a differently defined fit summary; check the definition rather than assuming variance explained.", "explanation": "Pseudo-R-squared describes a fit comparison defined for models such as logistic regression, often through likelihood-based quantities. Different definitions need not have identical interpretations or values. It is not automatically the ordinary fraction of response variation explained. Check the reported definition, and do not read it as classification accuracy or a probability for an individual case.", "links": [{"label": "ISLR tree-model resources", "url": "https://www.statlearning.com/online-courses"}, {"label": "StatQuest video catalog: classification and regression trees", "url": "https://statquest.org/video_index.html"}], "objective": "why-is-pseudo-r-squared-different-from-ordinary-r-squared"}, {"id": "R-260", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a true positive?", "answer": "Actually positive and predicted positive.", "explanation": "A true positive is a case that actually belongs to the chosen positive class and is predicted positive. If the positive event is a faulty item, correctly flagging a faulty item is a true positive. The word positive follows the defined event rather than whether the outcome is desirable. It contributes to both detected-positive and correct-prediction counts.", "links": [], "objective": "what-is-a-true-positive"}, {"id": "R-261", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a false positive?", "answer": "Actually negative but predicted positive.", "explanation": "A false positive is predicted positive even though its actual class is negative. For a fault detector, it is a good item incorrectly flagged as faulty. Its operational consequence may be unnecessary inspection or rejection. It enters the false-positive rate and the denominator of precision, which answer different conditional questions.", "links": [], "objective": "what-is-a-false-positive"}, {"id": "R-262", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a true negative?", "answer": "Actually negative and predicted negative.", "explanation": "A true negative actually belongs to the negative class and is predicted negative. For a fault detector, a good item correctly passed is a true negative. It contributes to specificity, negative predictive value, and overall accuracy through different denominators. Correct classification does not necessarily mean zero action cost; that depends on the stated decision-cost model.", "links": [], "objective": "what-is-a-true-negative"}, {"id": "R-263", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is a false negative?", "answer": "Actually positive but predicted negative.", "explanation": "A false negative is an actual positive case predicted negative. For a fault detector, a faulty item incorrectly passed is a false negative. It reduces recall because an actual positive was missed. Its cost may differ substantially from a false alarm, so a classifier with many correct negatives can still perform poorly for the important positive cases.", "links": [], "objective": "what-is-a-false-negative"}, {"id": "R-264", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is sensitivity or recall?", "answer": "TP/(TP+FN): the fraction of actual positives detected.", "explanation": "Sensitivity, or recall, conditions on actual positives: TP/(TP+FN). It asks what proportion of the positive cases were detected. If 18 of 20 actual faulty items are flagged, recall is 90%. It does not say what fraction of all flagged items are faulty; that separate question is precision.", "links": [], "objective": "what-is-sensitivity-or-recall"}, {"id": "R-265", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is specificity?", "answer": "TN/(TN+FP): the fraction of actual negatives correctly classified.", "explanation": "Specificity conditions on actual negatives: TN/(TN+FP). It asks what proportion of negative cases were correctly left negative. If 80 of 100 good items are passed, specificity is 80%. The false-positive rate is 1-specificity under the same convention. Specificity does not measure the correctness of positive predictions.", "links": [], "objective": "what-is-specificity"}, {"id": "R-266", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is precision or positive predictive value?", "answer": "TP/(TP+FP): the fraction of positive predictions that are correct.", "explanation": "Precision, or positive predictive value, conditions on predicted positives: TP/(TP+FP). It asks how often a positive flag is correct. If 15 of 30 flagged items are actually faulty, precision is 50%. This differs from recall, which conditions on actual faulty items. Precision can change with prevalence even when class-conditional detection rates stay fixed.", "links": [], "objective": "what-is-precision-or-positive-predictive-value"}, {"id": "R-267", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is overall accuracy?", "answer": "(TP+TN)/N.", "explanation": "Accuracy divides all correct predictions, TP+TN, by the total number of evaluated cases. It gives each case equal weight and does not distinguish the consequences of the two error types. A rare-positive problem can have high accuracy while missing most positives. Inspect relevant class metrics and costs instead of relying on the aggregate percentage alone.", "links": [], "objective": "what-is-overall-accuracy"}, {"id": "R-268", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is negative predictive value?", "answer": "TN/(TN+FN): the fraction of negative predictions that are correct.", "explanation": "Negative predictive value conditions on predicted negatives: TN/(TN+FN). It asks how often a negative prediction is correct. For example, 90 true negatives among 100 negative predictions give 90% NPV. Specificity instead conditions on actual negatives. The predictive value can depend on the prevalence of positives in the evaluated population.", "links": [], "objective": "what-is-negative-predictive-value"}, {"id": "R-269", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is ROC's pair of axes?", "answer": "x: false-positive rate. y: sensitivity/true-positive rate.", "explanation": "An ROC curve plots false-positive rate on the horizontal axis and true-positive rate, or sensitivity, on the vertical axis as the score threshold changes. Each point represents a different detection-versus-false-alarm tradeoff. The horizontal coordinate is 1-specificity, not precision. A curve summarizes ranking behavior but does not by itself select the most valuable threshold.", "links": [], "objective": "what-is-roc-s-pair-of-axes"}, {"id": "R-270", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does ROC AUC measure?", "answer": "How often a random positive scores above a random negative; a ranking measure.", "explanation": "ROC AUC summarizes how well scores rank positives above negatives across thresholds. It can be read as the probability that a randomly chosen positive scores above a randomly chosen negative, with ties conventionally receiving half credit. It does not establish calibrated probabilities, a specific threshold, or the classification accuracy at one chosen operating point.", "links": [], "objective": "what-does-roc-auc-measure"}, {"id": "R-271", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does AUC=.5 mean?", "answer": "Chance-level positive-versus-negative ranking, not necessarily 50% classification accuracy.", "explanation": "AUC of 0.5 indicates chance-level positive-versus-negative ranking under the AUC definition. Classification accuracy can still be far above 50% if one class dominates and the decision rule predicts that class. Thus ranking, threshold decisions, and class prevalence are different parts of evaluation. Do not translate the AUC directly into a percentage of correct classifications.", "links": [], "objective": "what-does-auc-5-mean"}, {"id": "R-272", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "How do prevalence changes affect evaluation?", "answer": "Precision, accuracy, and expected cost can change even if sensitivity and specificity stay fixed.", "explanation": "Prevalence determines how many evaluated cases belong to each actual class. Even with fixed sensitivity and specificity, changing that mix changes confusion counts and can change precision, accuracy, and expected cost. For example, rare positives can produce many false alarms relative to true detections. This transfer calculation assumes the class-conditional rates remain applicable.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}], "objective": "how-do-prevalence-changes-affect-evaluation"}, {"id": "R-273", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "Which confusion cells can contribute to decision cost, and how is cost totaled?", "answer": "All four can carry cost: multiply each count by its cell cost and add.", "explanation": "Total decision cost is cTP*TP+cFP*FP+cFN*FN+cTN*TN. All four cells can carry costs, including inspections or other actions that happen to be correct. Divide by the number of cases for average cost. Set correct-decision costs to zero only when specified, and do not substitute raw accuracy for a cost-weighted objective.", "links": [{"label": "ISLR classification and decision-rule resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "which-confusion-cells-can-contribute-to-decision-cost-and-how-is-cost-totaled"}, {"id": "R-274", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is expected cost at positive prevalence pi?", "answer": "pi*[Se*cTP+(1-Se)*cFN]+(1-pi)*[(1-Sp)*cFP+Sp*cTN], assuming the conditional rates transfer.", "explanation": "Weight each actual class by its prevalence, then its possible outcomes by their conditional rates and cell costs. The positive class contributes pi*[Se*cTP+(1-Se)*cFN]; the negative class contributes (1-pi)*[(1-Sp)*cFP+Sp*cTN]. This gives expected cost per case. Applying it to a new population assumes the relevant conditional rates and cost definitions transfer.", "links": [], "objective": "what-is-expected-cost-at-positive-prevalence-pi"}, {"id": "R-275", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is the cost-optimal positive threshold with calibrated p and correct decisions free?", "answer": "cFP/(cFP+cFN), when correct decisions cost zero and the stated probability/cost assumptions apply.", "explanation": "With calibrated probability p and zero cost for correct decisions, choosing positive has expected loss (1-p)*cFP; choosing negative has loss p*cFN. Comparing them gives threshold cFP/(cFP+cFN). If misses cost more, the threshold falls. This shortcut depends on those assumptions; nonzero correct-decision costs require the more general comparison of action losses.", "links": [{"label": "ISLR classification and decision-rule resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-is-the-cost-optimal-positive-threshold-with-calibrated-p-and-correct-decisions-free"}, {"id": "R-276", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does Poisson regression model?", "answer": "An expected count or arrival rate as a function of attributes.", "explanation": "Poisson regression relates predictors to an expected nonnegative count or arrival rate. A count mean can exceed one, unlike a binary-event probability. For example, it can estimate the expected number of calls in a defined interval. Define the observation or exposure interval so that counts or rates are comparable and the predicted quantity is clear.", "links": [], "objective": "what-does-poisson-regression-model"}, {"id": "R-277", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What are regression splines and knots?", "answer": "Polynomial pieces joined smoothly at knots.", "explanation": "A regression spline represents a relationship using polynomial pieces that meet at selected knot locations. Appropriate joining conditions make the fitted curve smooth instead of creating arbitrary jumps. Knot placement and flexibility are modeling choices. At survey depth, distinguish this piecewise curve representation from one global straight line without needing to derive the fitting machinery.", "links": [], "objective": "what-are-regression-splines-and-knots"}, {"id": "R-278", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does MARS stand for?", "answer": "Multivariate Adaptive Regression Splines.", "explanation": "MARS means Multivariate Adaptive Regression Splines. It is a regression approach using adaptively chosen piecewise relationships to represent nonlinear structure across predictors. The name connects it to spline-based modeling rather than classification voting or time-series differencing. For this survey scope, recognize its family and purpose without treating advanced implementation details as required knowledge.", "links": [], "objective": "what-does-mars-stand-for"}, {"id": "R-279", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What does Bayesian regression combine?", "answer": "Prior information about unknown quantities with observed data.", "explanation": "Bayesian regression combines a prior distribution describing information about unknown quantities with evidence from observed data. The resulting posterior represents updated uncertainty. A relevant prior can help when data are limited, while a misleading strong prior can distort estimates. The prior is not a set of fabricated known responses, and its suitability deserves scrutiny.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}], "objective": "what-does-bayesian-regression-combine"}, {"id": "R-280", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "stem": "What is k-NN regression's defining output rule?", "answer": "Average the numeric responses of the k nearest training cases.", "explanation": "k-NN regression finds nearby labeled training cases using the selected distance and averages their numeric responses. Responses of 4, 7, and 10 give prediction 7 for those three neighbors under simple averaging. Classification instead votes among categories. Scaling, irrelevant dimensions, neighborhood size, and the representativeness of nearby cases affect both methods.", "links": [], "objective": "what-is-k-nn-regression-s-defining-output-rule"}, {"id": "C-038", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "positive-class-reversal", "stem": "How do confusion cells change when the positive class is reversed?", "answer": "TP swaps with TN, and FP swaps with FN; accuracy stays unchanged.", "explanation": "Reversing which class is called positive swaps TP with TN and FP with FN. The total number of correct decisions remains unchanged, so accuracy stays the same. Class-conditional and predictive-value metrics can change because their denominators refer to the renamed event. Define the positive class before interpreting either a confusion table or its reported rates.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-039", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "threshold-gap", "stem": "Can changing a probability threshold leave every class decision unchanged?", "answer": "Yes. If no score crosses between the thresholds, the positive set stays the same.", "explanation": "A threshold changes decisions only when it passes one or more scores, subject to the equality convention. If no scores lie between 0.6 and 0.7, moving the cutoff within that gap can leave the positive set unchanged. Therefore increasing a threshold need not strictly reduce positive predictions or strictly improve any particular metric.", "links": []}, {"id": "C-040", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "ranking-versus-probability-values", "stem": "Why can models have equal AUC but different probability or threshold behavior?", "answer": "AUC depends on ranking; numerical probability values and fixed-threshold decisions can differ.", "explanation": "AUC depends on the ordering of positive and negative scores, rather than their exact probability values. Two models with the same ranking can therefore have equal AUC while giving different decisions at threshold 0.5 or differently calibrated probabilities. Evaluate ranking, probability quality, and operating-point consequences separately instead of assuming one ranking score establishes all three.", "links": [{"label": "StatQuest ROC video", "url": "https://youtu.be/4jRBRDbJemM"}, {"label": "StatQuest video catalog: confusion metrics", "url": "https://statquest.org/video_index.html"}]}, {"id": "C-041", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "prior-suitability", "stem": "Why should strong Bayesian prior information be scrutinized with little data?", "answer": "It can substantially influence updated estimates, especially when the observations provide limited evidence.", "explanation": "When observations provide little information, a strong prior can have substantial influence on Bayesian estimates. Check whether its population, context, and assumptions apply to the actual task. Relevant expertise can help, but confidence in an unsuitable prior does not make it valid. Interpret the result as a combination of prior information and data, rather than data alone.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}]}, {"id": "C-042", "module": 10, "topic": "Trees, probabilities, and decisions", "kind": "concept", "source": "Concept", "objective": "count-mean-versus-event-probability", "stem": "How does an expected count differ from a binary-event probability?", "answer": "A count mean can exceed one; an event probability lies between zero and one.", "explanation": "A count mean is the expected number of events in a defined setting and can exceed one. An event probability refers to whether a specified event occurs and must lie between zero and one. An expected count of three is not a 300% probability. Choose count regression or binary-event modeling according to the response actually needed.", "links": [{"label": "ISLR regression, nonlinear-model, and Bayesian companion resources", "url": "https://www.statlearning.com/online-courses"}]}]};
